export default JSON.parse('{"work":{"id":"wu-zi","schoolId":"military","title":"《吳子》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["wu-zi_ch-1","wu-zi_ch-2","wu-zi_ch-3","wu-zi_ch-4","wu-zi_ch-5","wu-zi_ch-6"],"totalChars":5906,"subtitle":"吳起"},"chapters":[{"id":"wu-zi_ch-1","workId":"wu-zi","order":1,"title":"圖國","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-1_p-1","wu-zi_ch-1_p-2","wu-zi_ch-1_p-3","wu-zi_ch-1_p-4","wu-zi_ch-1_p-5","wu-zi_ch-1_p-6","wu-zi_ch-1_p-7","wu-zi_ch-1_p-8"],"tags":[]},{"id":"wu-zi_ch-2","workId":"wu-zi","order":2,"title":"料敵","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-2_p-1","wu-zi_ch-2_p-2","wu-zi_ch-2_p-3","wu-zi_ch-2_p-4"],"tags":[]},{"id":"wu-zi_ch-3","workId":"wu-zi","order":3,"title":"治兵","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-3_p-1","wu-zi_ch-3_p-2","wu-zi_ch-3_p-3","wu-zi_ch-3_p-4","wu-zi_ch-3_p-5","wu-zi_ch-3_p-6","wu-zi_ch-3_p-7","wu-zi_ch-3_p-8"],"tags":[]},{"id":"wu-zi_ch-4","workId":"wu-zi","order":4,"title":"論將","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-4_p-1","wu-zi_ch-4_p-2","wu-zi_ch-4_p-3","wu-zi_ch-4_p-4","wu-zi_ch-4_p-5"],"tags":[]},{"id":"wu-zi_ch-5","workId":"wu-zi","order":5,"title":"應變","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-5_p-1","wu-zi_ch-5_p-2","wu-zi_ch-5_p-3","wu-zi_ch-5_p-4","wu-zi_ch-5_p-5","wu-zi_ch-5_p-6","wu-zi_ch-5_p-7","wu-zi_ch-5_p-8","wu-zi_ch-5_p-9","wu-zi_ch-5_p-10","wu-zi_ch-5_p-11"],"tags":[]},{"id":"wu-zi_ch-6","workId":"wu-zi","order":6,"title":"勵士","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-6_p-1","wu-zi_ch-6_p-2","wu-zi_ch-6_p-3","wu-zi_ch-6_p-4","wu-zi_ch-6_p-5","wu-zi_ch-6_p-6"],"tags":[]}],"passages":[{"id":"wu-zi_ch-1_p-1","chapterId":"wu-zi_ch-1","order":1,"canonicalText":"吳起儒服以兵機見魏文侯。文侯曰：「寡人不好軍旅之事。」起曰：「臣以見佔隱，以往察來，主君何言與心違。今君歲時屠宰，不以肥瘠，飾皮革，朱漆以文，此欲用之，非無用也。且君若無兵，雖有智謀，何以衛國？文武並用，雄霸之基也。」文侯乃親延之。","sentenceIds":["wu-zi_ch-1_p-1_s-1","wu-zi_ch-1_p-1_s-2","wu-zi_ch-1_p-1_s-3","wu-zi_ch-1_p-1_s-4","wu-zi_ch-1_p-1_s-5","wu-zi_ch-1_p-1_s-6","wu-zi_ch-1_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起穿著儒者的寬袍禮服，帶著深邃的軍事兵機前來拜見魏文侯。魏文侯說：寡人生平並不喜好窮兵黷武的軍事戰爭。吳起回答說：臣能夠從表面顯露的跡象推斷隱藏的實質，從過往的作為洞察未來的動向，主君您的言辭為何與內心真實意圖相違背呢？如今主君常年四時宰殺牲畜，挑選皮革製成堅甲，用朱紅生漆塗飾戰車盾牌，這明明是準備隨時用於軍事征戰，絕非擺設不用！況且主君若沒有強大的軍隊，縱有千般智謀，又拿什麼來保衛社稷國家呢？文治與武功並駕齊驅、兼收並蓄，這才是成就雄圖霸業的根本基石！魏文侯大為折服，隨即熱情延請吳起入座。","analysis":"【題解與吳起儒服見文侯論兼備文武】本段為《吳子・圖國》開篇，名將吳起以儒生裝束晉見魏文侯，一語道破文侯「言不喜兵、實修武備」的內心，確立「文武並用乃雄霸之基」的兵學核心綱領。\\n【詞義訓詁】「儒服」：儒者深衣禮帽；「以見佔隱」：見，顯現；佔，推斷；以顯露之表象推斷隱蔽之實質；「朱漆以文」：以紅漆彩繪兵器車甲；「文武並用」：內修文德、外整武備。\\n【兵儒合流特色】吳起曾受業於曾子，深得儒家內聖之學。《吳子》兵法最大特色即「文武合一、德刑並重」，將軍事征戰置於國家政治治理的整體框架之中。"}},{"id":"wu-zi_ch-1_p-2","chapterId":"wu-zi_ch-1","order":2,"canonicalText":"吳子曰：「昔之圖國家者，必先教百姓而親萬民。有四不和：不和於國，不可以出軍；不和於軍，不可以出陣；不和於陣，不可以進戰；不和於戰，不可以決勝。是以有道之主，將用其民，先和而造大事。」","sentenceIds":["wu-zi_ch-1_p-2_s-1","wu-zi_ch-1_p-2_s-2","wu-zi_ch-1_p-2_s-3","wu-zi_ch-1_p-2_s-4","wu-zi_ch-1_p-2_s-5","wu-zi_ch-1_p-2_s-6","wu-zi_ch-1_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：從前善於謀劃治理國家大計的聖君明相，必定首先教化百姓、團結親近普天下萬民。軍事行動有四大不可發動的不和戒律：若國家內部君民不和睦，絕不可貿然發兵出征；若軍隊內部上下官兵不和諧，絕不可拉到前線列隊出陣；若軍陣內部各兵種協同不和睦，絕不可下令向前推進作戰；若作戰部隊步調不協調，絕不可能奪取最終勝利！因此掌握治國大道的明君，在動員使用其百姓部隊之前，必定先凝聚人心內部和睦，然後才去興辦征戰統一大業。","analysis":"【題解與四不和與內部團結先於出兵】本段提出著名的「四不和」軍事鐵律：國不和不出軍、軍不和不出陣、陣不和不進戰、戰不和不決勝，確立「先和而後造大事」的戰爭哲學。\\n【詞義訓詁】「教百姓而親萬民」：先施以德教撫愛民心；「四不和」：國不和、軍不和、陣不和、戰不和；「造大事」：興辦軍國大事。\\n【政治決定軍事】吳起將「內部和諧與民心向背」視為戰爭勝利的第一前提。若內部派系傾軋、君民離心，縱有甲兵千萬亦必自潰於陣前。"}},{"id":"wu-zi_ch-1_p-3","chapterId":"wu-zi_ch-1","order":3,"canonicalText":"吳子曰：「夫道者，所以反本復始。義者，所以行事立功。謀者，所以違害就利。要者，所以保業守成。若行不合道，舉不合義，而處大居貴，患必及之。是以聖人綏之以道，理之以義，動之以禮，撫之以仁。此四德者，修之則興，廢之則衰。」","sentenceIds":["wu-zi_ch-1_p-3_s-1","wu-zi_ch-1_p-3_s-2","wu-zi_ch-1_p-3_s-3","wu-zi_ch-1_p-3_s-4","wu-zi_ch-1_p-3_s-5","wu-zi_ch-1_p-3_s-6","wu-zi_ch-1_p-3_s-7","wu-zi_ch-1_p-3_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：所謂道，是用來回歸本源、恪守天道根本的法則；所謂義，是用來推行政務、建立不朽功業的準繩；所謂謀，是用來避開禍患、趨向正當利益的策略；所謂要，是用來鞏固基業、保全既成成果的關鍵！如果統治者的行為不合乎天道，舉措不合乎道義，卻身居高位享有富貴，滅頂禍患必定會降臨其身！所以聖明的君王以道來安撫天下，以義來整飭綱紀，以禮來引導行動，以仁來撫育萬民。這四種崇高美德（道、義、禮、仁），修行實踐它國家便會繁榮昌盛，廢棄丟棄它國家便會衰敗滅亡！","analysis":"【題解與背景】\\n本段選自《吳子》〈圖國〉第 3 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰夫道者所以反本復始義者所以行事立功謀者……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「吳」、「子」、「夫」、「道」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wu-zi_ch-1_p-4","chapterId":"wu-zi_ch-1","order":4,"canonicalText":"吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。夫人有恥，在大足以戰，在小足以守矣。服者，所以彰德也；鼓角者，所以揚威也；刑賞者，所以示威信也。故賞不可不信，罰不可不武。進有重賞，退有死刑，雖有百萬之眾，如一人焉。」","sentenceIds":["wu-zi_ch-1_p-4_s-1","wu-zi_ch-1_p-4_s-2","wu-zi_ch-1_p-4_s-3","wu-zi_ch-1_p-4_s-4","wu-zi_ch-1_p-4_s-5","wu-zi_ch-1_p-4_s-6","wu-zi_ch-1_p-4_s-7","wu-zi_ch-1_p-4_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡治理國家統御軍隊，必須用禮儀法度來教育教化軍民，用大義公理來激勵鼓舞軍民，使人人都具備強烈的榮辱羞恥之心（使有恥）！人只要有了知恥之心，在戰略大規模進攻時足以及時奮勇作戰，在小規模防守時足以堅守陣地至死不退！軍服儀仗是用來彰顯德行威儀的，金鼓號角是用來激發昂揚威勢的，刑罰與賞賜是用來樹立國家最高威嚴與信義的！因此賞賜必定要信實兌現，懲罰必定要嚴肅果決！前進殺敵有豐厚重賞，畏縮退卻有軍法死刑，這樣即便指揮百萬大軍，行動起來也能像一個人一樣步調一致協同作戰！","analysis":"【題解與教禮勵義使有恥】吳起提出軍隊戰鬥力的核心心理機制——「使有恥（培育官兵榮譽感與羞恥心）」，並確立禮義教化與刑賞信武並重的治軍原則。\\n【詞義訓詁】「使有恥」：引導官兵以畏縮逃跑為恥、以勇敢殺敵為榮；「罰不可不武」：懲罰犯令者必須堅決果斷；「雖百萬之眾如一人」：高度組織化與高度紀律性。\\n【武德心理學】單靠嚴刑峻法只能使人畏懼，唯有結合禮義榮譽（有恥），部隊在生死關頭才能激發出「在小足以守、在大足以戰」的主動戰鬥意志。"}},{"id":"wu-zi_ch-1_p-5","chapterId":"wu-zi_ch-1","order":5,"canonicalText":"吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。其名又有五：一曰義兵，二曰強兵，三曰剛兵，四曰暴兵，五曰逆兵。禁暴救亂曰義，恃眾伐寡曰強，因怒興師曰剛，棄禮貪利曰暴，國亂人疲而舉事曰逆。五者之服，各有其道：義必以禮服，強必以謙服，剛必以辭服，暴必以詐服，逆必以權服。」","sentenceIds":["wu-zi_ch-1_p-5_s-1","wu-zi_ch-1_p-5_s-2","wu-zi_ch-1_p-5_s-3","wu-zi_ch-1_p-5_s-4","wu-zi_ch-1_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡戰爭爆發的根本根源有五種：第一是爭奪政治霸名（爭名），第二是爭奪經濟利益（爭利），第三是長期積累仇恨宿怨（積德惡），第四是國家爆發內部動亂（內亂），第五是遭遇災荒飢饉搶奪生存物資（因饑）。戰爭的性質名稱又分為五種：第一是義兵，第二是強兵，第三是剛兵，第四是暴兵，第五是逆兵。平息暴虐拯救動亂的軍隊叫做義兵；依仗人多勢眾侵略弱小的軍隊叫做強兵；因一時狂怒衝動而興兵的軍隊叫做剛兵；背棄禮義貪圖暴利的軍隊叫做暴兵；趁別國內亂百姓疲憊而發動非正義侵略的軍隊叫做逆兵！降伏這五種不同性質的敵軍，各自有其對應克制的戰略：對付義兵必須以崇高禮節求和相待，對付強兵必須以謙遜示弱誘其驕惰，對付剛兵必須以巧妙言辭化解其怒氣，對付暴兵必須以奇謀詐術設伏擊破，對付逆兵必須以靈活權變徹底制服！","analysis":"【題解與五兵之起與五兵之服】本段為軍事社會學與戰略分類學名篇，深刻剖析戰爭爆發的五大根源（名、利、惡、亂、飢）與五大性質（義、強、剛、暴、逆）及其精準克制之法。\\n【詞義訓詁】「積德惡」：德通得，積怨成仇；「義兵、強兵、剛兵、暴兵、逆兵」：古代戰爭正義性與動機之五大分類；「以權服」：以靈活戰略權謀制敵。\\n【戰略克敵法則】吳起反對用單一手段應對所有戰爭，強調先審查敵軍發兵動機與性質（知彼），對症下藥採取禮、謙、辭、詐、權等針對性戰略，極具博弈智慧。"}},{"id":"wu-zi_ch-1_p-6","chapterId":"wu-zi_ch-1","order":6,"canonicalText":"武侯問曰：「願聞治兵、料人、固國之道。」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。昔齊桓公九合諸侯，一匡天下，管仲之謀也。晉文公出定襄王，踐土之盟，狐偃之功也。故得賢者昌，失賢者亡。君其務在得人。」","sentenceIds":["wu-zi_ch-1_p-6_s-1","wu-zi_ch-1_p-6_s-2","wu-zi_ch-1_p-6_s-3","wu-zi_ch-1_p-6_s-4","wu-zi_ch-1_p-6_s-5","wu-zi_ch-1_p-6_s-6","wu-zi_ch-1_p-6_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯向吳起詢問道：寡人希望聽聞治理軍隊、考量人才、鞏固國家的根本大道。吳起回答說：古代的聖明君王，必定嚴肅謹守君臣尊卑的禮節，修飾整肅上下長幼的禮儀，安撫聚集官吏百姓，順應民風民俗推行教化，精選招募優秀精良的人才，以防備不可預料的突發變故。從前齊桓公九次大會天下諸侯、一匡天下稱霸中原，依靠的是賢相管仲的深謀遠慮；晉文公率軍護送安定周襄王、在踐土大會諸侯成就霸業，依靠的是謀臣狐偃的不朽功勳！所以得到賢才輔佐的國家必定昌盛，失去賢才輔佐的國家必定滅亡。主君當前最緊迫的要務，正在於求賢若渴、招攬任用天下賢才！","analysis":"【題解與背景】\\n本段選自《吳子》〈圖國〉第 6 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰願聞治兵料人固國之道起對曰古之明王必……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「武」、「侯」、「問」、「願」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wu-zi_ch-1_p-7","chapterId":"wu-zi_ch-1","order":7,"canonicalText":"武侯問曰：「願聞陳必定、守必固、戰必勝之道。」起對曰：「立見且可，豈直聞乎！君能使賢者居上，不肖者居下，則陳已定矣；民安其田宅，親其官長，則守已固矣；百姓皆是吾君而非鄰國，則戰已勝矣。」","sentenceIds":["wu-zi_ch-1_p-7_s-1","wu-zi_ch-1_p-7_s-2","wu-zi_ch-1_p-7_s-3","wu-zi_ch-1_p-7_s-4","wu-zi_ch-1_p-7_s-5","wu-zi_ch-1_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯詢問道：寡人希望聽聞如何能使軍陣必定穩定不亂、城池防守必定固若金湯、作戰交鋒必定奪取勝利的根本大道。吳起回答說：這些效果立刻就能親眼見證，哪裡僅僅是口頭聽聞而已呢！主君若能做到讓德才兼備的賢能者身居上位，讓平庸無能之輩位居下位，那麼國家的陣勢就已經穩定不可動搖了；讓百姓安居於田畝宅院、親近愛戴管轄自己的官長，那麼國家的防守就已經固若金湯了；全體百姓皆擁戴讚同我們的主君、而厭棄反對敵對鄰國的暴政，那麼對外作戰就已經在政治上鎖定勝利了！","analysis":"【題解與背景】\\n本段選自《吳子》〈圖國〉第 7 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰願聞陳必定守必固戰必勝之道起對曰……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-1_p-7）。"}},{"id":"wu-zi_ch-1_p-8","chapterId":"wu-zi_ch-1","order":8,"canonicalText":"武侯嘗謀事，群臣莫能及，罷朝而有喜色。起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。申公巫臣問曰：『君何為有憂色？』莊王曰：『諸侯自以為不及人者，乃能得師。今群臣莫及寡人，楚國其殆矣！』此楚莊王之所以憂，而君反以為喜，臣是以懼也。」武侯慚。","sentenceIds":["wu-zi_ch-1_p-8_s-1","wu-zi_ch-1_p-8_s-2","wu-zi_ch-1_p-8_s-3","wu-zi_ch-1_p-8_s-4","wu-zi_ch-1_p-8_s-5","wu-zi_ch-1_p-8_s-6","wu-zi_ch-1_p-8_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯有一次在朝廷謀劃國家大事，滿朝大臣的智謀才智沒有一人能趕得上武侯，武侯退朝之後臉上洋溢著得意歡喜的神色。吳起上前進言道：從前春秋楚莊王有一次謀劃國事，滿朝群臣的見解沒有一人能比得上莊王，莊王退朝之後臉上卻充滿了深深的憂慮神色。大臣申公巫臣詢問說：主君為何面帶憂色？莊王回答說：諸侯君王只有自知才智不如賢能之人、虛懷若谷，才能招攬到天下名師輔佐；如今滿朝大臣的才智謀略竟然都不如我寡人一人，我楚國的前途恐怕極其危險了啊！這正是當年楚莊王之所以憂患的緣故，而主君如今卻反過來以此為傲沾沾自喜，臣私下因此深感恐懼擔憂啊！魏武侯聽後深感慚愧。","analysis":"【題解與楚莊王群臣不及而憂】本段為千古名諫——吳起引楚莊王退朝有憂色之典故，當頭棒喝魏武侯盲目自大、壓抑臣下之弊，促其虛懷納諫。\\n【詞義訓詁】「莫能及」：無人能比得上；「申公巫臣」：春秋楚國名臣；「楚國其殆」：楚國危殆；「君反以為喜」：反以為榮，缺乏危機意識。\\n【領導者心態之最高境界】傑出的最高統治者若發現下屬皆不如己，應警惕人才匱乏與言路閉塞之危局（退朝有憂色）；若盲目自得，終將陷入兼聽則明、偏信則暗的盲目深淵。"}},{"id":"wu-zi_ch-2_p-1","chapterId":"wu-zi_ch-2","order":1,"canonicalText":"武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。六國兵四守，勢甚不便，為之奈何？」起對曰：「夫齊性剛，其政猛，民貪而吏輕，故其陳重而不能久，破之必分其兵。秦性強，其政嚴，民勇而多詐，故其陳散而自為戰，破之必以利誘。楚性弱，其政亂，民疲而力散，故其陳整而不能守，破之必驚其氣。趙性平，其政和，民勞而力拙，故其陳固而不能進，破之必薄其前。燕性慤，其政愚，民慎而無謀，故其陳密而不能動，破之必衝其後。韓性端，其政定，民疲而少戰，故其陳正而不能奇，破之必乘其隙。此六國之情也。」","sentenceIds":["wu-zi_ch-2_p-1_s-1","wu-zi_ch-2_p-1_s-2","wu-zi_ch-2_p-1_s-3","wu-zi_ch-2_p-1_s-4","wu-zi_ch-2_p-1_s-5","wu-zi_ch-2_p-1_s-6","wu-zi_ch-2_p-1_s-7","wu-zi_ch-2_p-1_s-8","wu-zi_ch-2_p-1_s-9","wu-zi_ch-2_p-1_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯對吳起說：如今強秦在西方威脅我國西境，大楚在南方環繞逼近，趙國在北方衝擊我國邊界，強齊在東方雄踞逼臨，燕國隔斷在我們後方，韓國扼據在我們正前方。六國大軍四面包圍守控，我魏國處境極為不利，對此該如何應對呢？吳起回答說：齊國人民生性剛烈，其政令暴猛，百姓貪圖私利而官吏輕浮，因此其軍陣重厚卻無法長久堅持，要擊破齊軍必須誘使其分散兵力。秦國人民生性強悍，其法度嚴酷，百姓勇武而多用詐術，因此其軍陣分散且各自為戰，要擊破秦軍必須用利益誘其入伏。楚國人民生性柔弱，其朝政混亂，百姓疲憊而力量渙散，因此其軍陣看似齊整卻難以持久堅守，要擊破楚軍必須發動突襲重挫其軍心士氣。趙國人民生性平和，其政令寬和，百姓勞苦而作戰技巧笨拙，因此其軍陣穩固卻難以主動進攻，要擊破趙軍必須全力壓制其陣前主力。燕國人民生性謹慎老實，其政令愚鈍，百姓謹小慎微而缺乏機謀，因此其軍陣密集卻難以靈活機動，要擊破燕軍必須從背後發起猛烈衝擊。韓國人民生性端正，其政局穩定，百姓疲憊而少經大戰，因此其軍陣端正卻缺乏奇謀變通，要擊破韓軍必須乘其防守破綻發動致命一擊！這就是六國各自的民風性格、政局特點與破敵戰術！","analysis":"【題解與審度戰國六國兵性與破敵戰術】本段為《戰國策》與先秦軍事心理學、地緣戰略分析之巔峰名篇——吳起對齊、秦、楚、趙、燕、韓六國國民性格、政治制度、軍陣特徵及克敵戰術進行了全方位透徹剖析！\\n【詞義訓詁】「齊性剛、秦性強、楚性弱、趙性平、燕性慤、韓性端」：六國國民性格與文化心理之精準概括；「慤」：音確，誠實拘謹；「六國之情」：知己知彼之情報戰略。\\n【軍事心理學與定制化作戰】吳起開創了「因敵而異、對症施策」的定制化作戰理論：不對不同敵人使用同一戰術，而是精確針對其心理弱點與陣形死穴實施打擊。"}},{"id":"wu-zi_ch-2_p-2","chapterId":"wu-zi_ch-2","order":2,"canonicalText":"吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；二曰盛夏炎熱，晏興無息，行飢渴，千里不絕；三曰師久淹留，糧草乏絕，百姓怨嗟，妖祥數起；四曰軍資既竭，薪芻既乏，天雨霖霪，欲取無所；五曰徒眾不多，水地不便，人馬疲病，四鄰不救；六曰道遠日暮，士卒勞倦，飢餒未食，解甲而息；七曰將吏卑弱，士卒不和，動靜無常，三軍易駭；八曰陳隊未定，舍壘未成，傾險狹路，半度而擊。此八者，擊之必勝，無疑也。」","sentenceIds":["wu-zi_ch-2_p-2_s-1","wu-zi_ch-2_p-2_s-2","wu-zi_ch-2_p-2_s-3","wu-zi_ch-2_p-2_s-4","wu-zi_ch-2_p-2_s-5","wu-zi_ch-2_p-2_s-6","wu-zi_ch-2_p-2_s-7","wu-zi_ch-2_p-2_s-8","wu-zi_ch-2_p-2_s-9","wu-zi_ch-2_p-2_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡審度敵情，有八種情況無須占卜便可果斷發起進攻、必定奪取全勝：\\n第一，狂風呼嘯嚴寒刺骨，敵軍清晨摸黑早起行軍遷徙，伐木鋪路冒險渡河，疲於奔命；\\n第二，盛夏酷暑烈日當空，敵軍行軍日暮不得喘息，忍飢挨渴長途跋涉千里不絕；\\n第三，敵軍長久出征滯留外地，糧草斷絕物資匱乏，士卒百姓怨聲載道，軍中怪異凶兆頻生；\\n第四，敵軍物資耗盡，柴草燃料枯竭，連日陰雨連綿不絕，糧秣搜刮無門；\\n第五，敵軍兵力寡少，地形水土不服，人馬疲憊疾病流行，周邊盟友孤立不救；\\n第六，道路遙遠天色已晚，士卒疲憊勞倦，飢腸轆轆尚未進食，卸下甲胄正在歇息；\\n第七，敵方將領威望低劣怯懦，士卒內部爭吵不和，行軍動靜毫無常軌，全軍極易驚恐慌亂；\\n第八，敵軍陣隊尚未排列成形，營壘柵欄尚未修築完成，行經險隘峽谷狹路，或是部隊渡河剛過一半之時！以上這八種敵情，果斷出擊必獲大勝，絲毫無須懷疑！","analysis":"【題解與背景】\\n本段選自《吳子》〈料敵〉第 10 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰凡料敵有不卜而與之戰者八一曰疾風大……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「吳」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-2_p-2）。"}},{"id":"wu-zi_ch-2_p-3","chapterId":"wu-zi_ch-2","order":3,"canonicalText":"吳子曰：「凡料敵有不占而避之者六：一曰土地廣大，人民富盛；二曰上愛其下，惠施流布；三曰賞罰信明，動靜及時；四曰陳列勇銳，將明兵精；五曰兵革備具，資糧充饒；六曰四鄰合從，大國為援。凡見此六者，審避之勿疑。敵若可進則進，不可進則退，此知兵之大要也。」","sentenceIds":["wu-zi_ch-2_p-3_s-1","wu-zi_ch-2_p-3_s-2","wu-zi_ch-2_p-3_s-3","wu-zi_ch-2_p-3_s-4","wu-zi_ch-2_p-3_s-5","wu-zi_ch-2_p-3_s-6","wu-zi_ch-2_p-3_s-7","wu-zi_ch-2_p-3_s-8","wu-zi_ch-2_p-3_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡審度敵情，有六種情況無須占卜便應當主動迴避退讓、不可輕舉妄動：\\n第一，敵國疆域廣袤廣大，人口眾多經濟富庶；\\n第二，敵國君主深愛體恤其臣民，仁愛恩惠廣泛普施；\\n第三，敵軍賞罰信實嚴明，軍隊調動動靜極其精準及時；\\n第四，敵軍陣容嚴整勇銳，將領英明而士卒精悍；\\n第五，敵軍武器裝備精良完備，糧草儲備充足豐饒；\\n第六，敵國周邊鄰邦緊密結盟，背後有強大大國作為強大外援！大凡遇見具備這六種優勢的敵軍，務必審慎主動退避，切莫遲疑不決！敵人有破綻可進攻則果斷進攻，不可進攻則堅決主動退避，這正是懂得用兵之道的至高綱領！","analysis":"【題解與六不占而避之戰略避險】吳起從政治、經濟、民心、賞罰、軍事、外交六大維度，論述敵軍處於強盛健全時必須堅決避其鋒芒的戰略自律。\\n【詞義訓詁】「不占而避」：敵強我不可輕戰，主動退避以待其變；「惠施流布」：恩惠施及全體百姓；「四鄰合從」：外交聯盟穩固。\\n【戰略克制與風險控制】《孫子兵法》云「不可勝在己，可勝在敵」。在敵方無懈可擊時盲目冒進必致滅頂，懂得主動退避（審避之）才是真正的成熟統帥。"}},{"id":"wu-zi_ch-2_p-4","chapterId":"wu-zi_ch-2","order":4,"canonicalText":"武侯問曰：「敵眾我寡，敵強我弱，為之奈何？」起對曰：「避之於易，邀之於隘。故曰：以一擊十，莫善於隘；以十擊百，莫善於險；以千擊萬，莫善於阻。今有少眾，卒起於深草狹路之中，擊其半渡，斷其後陳，則敵雖眾，亦可破也。」","sentenceIds":["wu-zi_ch-2_p-4_s-1","wu-zi_ch-2_p-4_s-2","wu-zi_ch-2_p-4_s-3","wu-zi_ch-2_p-4_s-4","wu-zi_ch-2_p-4_s-5","wu-zi_ch-2_p-4_s-6","wu-zi_ch-2_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯詢問道：如果敵軍人多勢眾而我軍兵力寡少，敵軍實力強大而我軍實力弱小，面對這種局勢該如何應對呢？吳起回答說：在平坦開闊的平原上避開敵人的鋒芒（避之於易），在狹窄險隘的地形截擊敵人的部隊（邀之於隘）！所以兵法說：用一人襲擊十人，沒有比狹窄隘道更好的地形了；用十人圍攻百人，沒有比險峻山隘更好的地形了；用一千人擊破一萬人，沒有比險阻關隘更好的地形了！如今我方兵力雖少，只要突然從深密叢草或狹窄險路中伏兵殺出，趁其渡河渡水渡到一半時發起截擊，切斷其後方大部隊陣列，那麼敵人兵力縱有千軍萬馬，也必定會被我軍徹底擊潰破滅！","analysis":"【題解與以少勝多避易邀隘之術】本段為古典兵法以少勝多之經典戰術準則——利用險隘狹阻地形限制敵軍兵力展開，以局部優勢消滅整體優勢。\\n【詞義訓詁】「避之於易，邀之於隘」：易，平坦平原；隘，狹窄山口；「以一擊十莫善於隘」：地形縮小兵力接觸面；「擊其半渡」：半渡擊之。\\n【地形戰術放大器】在開闊平原上大兵團作戰取決於兵力總量；在狹窄峽谷中，敵軍再多也只能以少數兵力正面接觸。巧妙利用地形，便能實現「以少勝多、以弱勝強」。"}},{"id":"wu-zi_ch-3_p-1","chapterId":"wu-zi_ch-3","order":1,"canonicalText":"吳子曰：「夫進路退路，乃戰之大端。凡治兵者，必先教令為先。教令明，則進退一；進退一，則三軍齊。三軍齊，則動靜同。動靜同，則威武立矣。」","sentenceIds":["wu-zi_ch-3_p-1_s-1","wu-zi_ch-3_p-1_s-2","wu-zi_ch-3_p-1_s-3","wu-zi_ch-3_p-1_s-4","wu-zi_ch-3_p-1_s-5","wu-zi_ch-3_p-1_s-6","wu-zi_ch-3_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：部隊前進的進路與撤退的退路，是戰爭作戰的最關鍵大綱。大凡統帥治理軍隊，必須把明確操演政令教導置於首要地位！教導與號令清晰明確，部隊前進與後退才能統一協調；前進與後退統一協調，三軍將士才能步伐齊整；三軍將士步伐齊整，全軍調動與靜止才能如同一人；調動與靜止完全同步，全軍的威武氣勢便巍然樹立了！","analysis":"【題解與背景】\\n本段選自《吳子》〈治兵〉第 13 節。屬於古代傳統經典之精華篇章，記述先賢關於立德立言、治國用兵與天地自然哲理之重大名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰：「夫進路退路，乃戰之大端。凡……」之思想精華與章法結構。\\n2. 訓詁與語法考釋：本段重點解讀「吳」、「子」等字詞之古代漢語語意、通假字與名物制度規範。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\\n考釋特別補充：本段體現了傳統文化博大精深之學術源流與治國安邦哲理。"}},{"id":"wu-zi_ch-3_p-2","chapterId":"wu-zi_ch-3","order":2,"canonicalText":"吳子曰：「金鼓旌旗，所以肅視聽也。視旌旗之指而動，聽金鼓之聲而進。鼓之則進，金之則止；麾之則左，旗之則右。號令既宣，犯令者誅。賞必及時，罰必當罪。如此，則三軍之士，見利不敢先，見危不敢退矣。」","sentenceIds":["wu-zi_ch-3_p-2_s-1","wu-zi_ch-3_p-2_s-2","wu-zi_ch-3_p-2_s-3","wu-zi_ch-3_p-2_s-4","wu-zi_ch-3_p-2_s-5","wu-zi_ch-3_p-2_s-6","wu-zi_ch-3_p-2_s-7","wu-zi_ch-3_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：金鑼、戰鼓與旌旗旗幟，是用來嚴肅統一全軍將士視覺與聽覺的信號指揮系統！看著旌旗指向的方向而行動，聽著戰鼓金鑼的節奏聲音而前進！擊戰鼓則奮勇向前衝鋒，鳴金鑼則立即停止駐紮；左揮軍旗則向左轉向，右揮軍旗則向右調動！作戰號令一旦向全軍宣達，膽敢違犯軍令者立斬不赦！有功賞賜必定及時兌現，有罪懲罰必定罪罰相當！如果做到這樣，那麼三軍全體將士，見到戰功私利不敢擅自搶先冒進，面臨生死危險不敢擅自潰退後逃！","analysis":"【題解與金鼓旌旗信號指揮與軍法威信】吳起詳述先秦軍隊通訊指揮系統（金鼓聽覺、旌旗視覺）之運作規則，以及嚴明軍紀對部隊執行力之保障。\\n【詞義訓詁】「肅視聽」：統一嚴肅全軍耳目感官；「鼓進金止」：擊鼓衝鋒、鳴金收兵；「見利不敢先，見危不敢退」：行動完全聽從指揮。\\n【戰場指揮控制系統（C2）】在冷兵器時代的大規模戰場上，金鼓與旌旗是唯一的實時指揮控制系統。唯有通過日常嚴格操練，才能保證戰場命令的毫秒級傳達與執行。"}},{"id":"wu-zi_ch-3_p-3","chapterId":"wu-zi_ch-3","order":3,"canonicalText":"吳子曰：「治兵有三戒：一曰無以重勞擊輕安，二曰無以大飢擊大飽，三曰無以大亂擊大整。夫能避其所不能，擊其所能，則萬戰萬勝矣。」","sentenceIds":["wu-zi_ch-3_p-3_s-1","wu-zi_ch-3_p-3_s-2","wu-zi_ch-3_p-3_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：治理統率軍隊作戰有三大嚴格禁戒：第一，絕不可用極度疲憊勞累的部隊去進攻以逸待勞輕鬆安逸的敵軍；第二，絕不可用飢腸轆轆糧餉斷絕的部隊去進攻飽食充飢儲備充足的敵軍；第三，絕不可用內部混亂動盪的部隊去進攻陣容嚴整訓練有素的敵軍！大凡能夠主動避開己方條件不足的劣勢局面，專門挑選己方具備絕對把握的戰機發起攻擊，那麼就能達到打一萬次仗、贏得一萬次勝利的境界！","analysis":"【題解與背景】\\n本段選自《吳子》〈治兵〉第 15 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰治兵有三戒一曰無以重勞擊輕安二曰無以大……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「吳」、「子」、「治」、「兵」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wu-zi_ch-3_p-4","chapterId":"wu-zi_ch-3","order":4,"canonicalText":"吳子曰：「凡治兵者，必知氣機。氣實則鬥，氣奪則走。三軍之眾，百萬之師，志厲青雲，氣若風雷，此所謂氣盛也。將以禮先之，以義厲之，以威嚴之，以恩撫之，則三軍之氣蓄矣。」","sentenceIds":["wu-zi_ch-3_p-4_s-1","wu-zi_ch-3_p-4_s-2","wu-zi_ch-3_p-4_s-3","wu-zi_ch-3_p-4_s-4","wu-zi_ch-3_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡統御治理軍隊的將帥，必須深刻洞悉全軍將士的士氣轉移規律（氣機）！士氣充沛充實則將士奮勇死戰，士氣遭到挫傷被奪則全軍潰逃奔走！三軍成千上萬的將士，百萬之眾的大軍，鬥志高昂凌駕於青雲之上，殺氣奔湧如同風雷激盪，這就是所謂的士氣旺盛！統帥若能以禮節率先以身作則，以大義激勵將士鬥志，以嚴明軍威整飭紀律，以慈愛恩惠撫慰士卒疾苦，那麼全軍將士的昂揚士氣便能充盈積蓄爆發出來了！","analysis":"【題解與知氣機與蓄養三軍士氣】本段闡發吳子兵法獨具特色之「氣機（心理士氣）」理論，論述將帥如何通過禮、義、威、恩四管齊下蓄養三軍浩然士氣。\\n【詞義訓詁】「氣機」：士氣生發與轉移之關鍵樞紐；「氣實則鬥，氣奪則走」：士氣決定戰鬥意志；「志厲青雲」：志向高遠昂揚。\\n【戰鬥精神培育】吳起指出部隊戰鬥力不僅在於裝備，更在於無形的心靈士氣。以恩義凝聚、以威禮引導，方能激發出排山倒海的戰鬥精神。"}},{"id":"wu-zi_ch-3_p-5","chapterId":"wu-zi_ch-3","order":5,"canonicalText":"吳子曰：「短兵長兵，各有其用。短兵利於險隘，長兵利於平易。弩利於遠射，弓利於速發，矛戟利於刺擊，刀劍利於近鬥。短長相雜，遠近相資，此治兵之良法也。」","sentenceIds":["wu-zi_ch-3_p-5_s-1","wu-zi_ch-3_p-5_s-2","wu-zi_ch-3_p-5_s-3","wu-zi_ch-3_p-5_s-4","wu-zi_ch-3_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：短兵刃武器與長兵器武器，各自有其特定的戰術功用！短兵刃（刀劍短矛）利於在狹窄險隘、山林叢林中發揮威力；長兵器（長槍長戟）利於在平坦開闊的平原上列陣刺殺！強弩利於超遠距離精準射擊穿甲，長弓利於近距離快速連續發射，長矛與長戟利於突刺穿擊衝鋒，單刀與寶劍利於近身貼身搏鬥！長短兵器相互穿插配合，遠射與近戰武器互相支援補充，這正是編制訓練軍隊的絕妙良法！","analysis":"【題解與兵器配置與長短相資】吳起系統論述冷兵器時代各類武器（長兵、短兵、弓、弩、矛、戟、刀、劍）的戰術特徵與步兵多兵種協同作戰原則。\\n【詞義訓詁】「短兵長兵」：短柄與長柄冷兵器；「長短相雜，遠近相資」：遠程火力與近戰格鬥互補之合成步兵陣形。\\n【步兵武器合成化】吳起親自訓練的「魏武卒」之所以所向無敵，關鍵在於建立了長短兼備、遠近協同的合成作戰編制，使敵軍在任何距離皆遭遇嚴密打擊。"}},{"id":"wu-zi_ch-3_p-6","chapterId":"wu-zi_ch-3","order":6,"canonicalText":"吳子曰：「夫教人以戰，如教童子。以一人教十人，十人教百人，百人教千人，千人教萬人，萬人教三軍。教之以坐作進退，習之以疾徐俯仰，練之以合散聚分。日日操之，歲歲習之，則民皆精熟，臨戰不惑矣。」","sentenceIds":["wu-zi_ch-3_p-6_s-1","wu-zi_ch-3_p-6_s-2","wu-zi_ch-3_p-6_s-3","wu-zi_ch-3_p-6_s-4","wu-zi_ch-3_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：教導訓練百姓將士作戰，就如同啟蒙教導孩童讀書一樣循序漸進。由一名優秀教官訓練十名骨幹，十名骨幹再去訓練一百名士兵，一百名士兵再去訓練一千人，一千人再去推廣訓練一萬人，一萬人最終教化普及到整個三軍部隊！教導他們熟練掌握起立、端坐、前進、後退的步調，訓練他們適應奔跑、慢行、俯身避箭、仰身射擊的動作，操練他們掌握陣隊聚合、分散、包圍、分進的陣法變換！每天堅持操練不懈，長年累月養成肌肉記憶習慣，那麼全體士兵皆精通熟練作戰技能，親臨戰場生死之際也絕不會迷惘慌亂了！","analysis":"【題解與以一人教十人層級軍訓法】本段記錄吳起創立的「裂變式層級軍事訓練法（以一教十、十教百、百教千）」與動作標準化條令訓練體系。\\n【詞義訓詁】「教童子」：由淺入深、循序漸進；「坐作進退」：古代步兵基本戰術操典（起立、跪坐、進擊、撤退）；「合散聚分」：大兵團陣形變換訓練。\\n【近代軍事操典先河】吳起將繁複的作戰技能分解為標準動作，通過骨幹梯隊裂變式培訓，使數萬新兵迅速轉化為精銳武卒，開創現代軍事操典訓練之先河。"}},{"id":"wu-zi_ch-3_p-7","chapterId":"wu-zi_ch-3","order":7,"canonicalText":"吳子曰：「凡戰之法，五人為伍，十人為什，百人為卒，千人為旅，萬人為軍。伍長管其伍，什長管其什，卒長管其卒，旅長管其旅，軍將管其軍。各守其分，各盡其職，大不得掩小，貴不得凌賤。上下相安，法度明備，此治兵之經也。」","sentenceIds":["wu-zi_ch-3_p-7_s-1","wu-zi_ch-3_p-7_s-2","wu-zi_ch-3_p-7_s-3","wu-zi_ch-3_p-7_s-4","wu-zi_ch-3_p-7_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡編制軍隊作戰的法度：五人編成一個戰鬥基層小組（伍），十人編成一個什，一百人編成一個卒，一千人編成一個旅，一萬人編成一個獨立軍團！伍長負責管轄約束其五名組員，什長負責管轄其十人小隊，卒長負責指揮其百人連隊，旅長負責統率其千人部隊，軍將負責總攬指揮全軍！各級指揮官恪守各自的職權分工，各自竭盡全力履行本職責任，高級軍官不得隨意越權包辦下級職責，尊貴將領不得隨意欺凌低賤士兵！上下級和睦相處相安無事，各項法度條令明確完備，這正是治理訓練軍隊的根本常規常道！","analysis":"【題解與什伍編制與層級管理責任制】吳起闡述先秦軍隊經典的五進制編制體系（伍、什、卒、旅、軍）與嚴格的層級責任授權機制。\\n【詞義訓詁】「五人為伍，十人為什」：中國古代基層軍隊與戶籍編制；「各守其分」：各守職權邊界、嚴禁越權瞎指揮；「大不掩小」：充分發揮基層軍官主觀能動性。\\n【科層制軍事組織】明確指揮鏈條與權責邊界，使龐大軍隊具備高度模組化與容錯能力，基層即便失去統帥亦能以伍什為單位自主作戰。"}},{"id":"wu-zi_ch-3_p-8","chapterId":"wu-zi_ch-3","order":8,"canonicalText":"吳子曰：「凡行軍之法，無犯絕水，無逆天時，無臨深谷，無背高山。若在平陸，則佔廣易；若在山林，則佔險阻。審察地形，因利制勝。兵不預習，臨戰必擾；馬不預習，臨陳必驚。故治兵者，貴在素習也。」","sentenceIds":["wu-zi_ch-3_p-8_s-1","wu-zi_ch-3_p-8_s-2","wu-zi_ch-3_p-8_s-3","wu-zi_ch-3_p-8_s-4","wu-zi_ch-3_p-8_s-5","wu-zi_ch-3_p-8_s-6","wu-zi_ch-3_p-8_s-7","wu-zi_ch-3_p-8_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡大軍行軍推進的法則：切莫渡過險阻絕水深潭，切莫違逆極端天時氣象，切莫緊貼懸崖深谷行軍，切莫背靠孤立高山紮營！如果作戰在平原曠野平陸之上，就應當佔據開闊平坦的地形展開兵力；如果作戰在崇山峻嶺山林之中，就應當佔據險要關隘依險防守！仔細審度明察周邊地形特徵，因應有利形勢制取勝利！士兵若未經過平時預先操習，親臨實戰必定慌亂無措；戰馬若未經過平時預先訓練，親臨軍陣衝鋒必定受驚狂奔！所以善於治理軍隊的將帥，最寶貴的在於平時嚴格素習訓練！","analysis":"【題解與背景】\\n本段選自《吳子》〈治兵〉第 20 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰凡行軍之法無犯絕水無逆天時無臨深谷……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「吳」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-3_p-8）。"}},{"id":"wu-zi_ch-4_p-1","chapterId":"wu-zi_ch-4","order":1,"canonicalText":"吳子曰：「夫總文武者，軍之將也；兼剛柔者，兵之事也。凡人論將，常思其勇；勇之於將，乃數分之一耳。夫勇者必輕合，輕合而不知利，未可也。故將有五慎：一曰理，二曰備，三曰果，四曰戒，五曰約。理者，治眾如治寡；備者，出門如見敵；果者，臨敵不懷生；戒者，雖克如始戰；約者，法令省而不煩。修此五者，乃可為大將矣。」","sentenceIds":["wu-zi_ch-4_p-1_s-1","wu-zi_ch-4_p-1_s-2","wu-zi_ch-4_p-1_s-3","wu-zi_ch-4_p-1_s-4","wu-zi_ch-4_p-1_s-5","wu-zi_ch-4_p-1_s-6","wu-zi_ch-4_p-1_s-7","wu-zi_ch-4_p-1_s-8","wu-zi_ch-4_p-1_s-9","wu-zi_ch-4_p-1_s-10","wu-zi_ch-4_p-1_s-11","wu-zi_ch-4_p-1_s-12","wu-zi_ch-4_p-1_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：能夠總攬貫通文治與武功的人，才能出任全軍的最高統帥大將；能夠兼具剛強與陰柔之道的人，才能勝任軍事征戰的大事！尋常世人談論將領，往往只片面看重其個人勇武；然而勇武對於一名統帥而言，不過是其必備素質中的幾分之一罷了！因為單純勇猛的人必定容易輕率與敵人交鋒，輕率交鋒而不知戰略利害得失，是根本不可行的！所以身為統帥大將必須恪守五慎：第一是理，第二是備，第三是果，第四是戒，第五是約！所謂理，是指治理百萬大軍如同指揮少數人一樣井井有條；\\n所謂備，是指大軍一踏出營門就如同隨時面臨強敵一樣戒備森嚴；\\n所謂果，是指親臨敵陣交戰之際決死向前、絕不苟且偷生；\\n所謂戒，是指縱然奪取了戰役勝利，防備警戒依然如同剛開戰時一樣嚴密不懈；\\n所謂約，是指頒布的條令法規簡約明白而絕不繁雜苛細！能夠完滿修持這五種品德的將領，才能夠勝任統領三軍的真正大將！","analysis":"【題解與將之五慎理備果戒約】本段為中國古代將領考選與品德標準之最權威文獻——吳起批判「匹夫之勇」，確立「總文武、兼剛柔、五慎（理、備、果、戒、約）」之儒將大帥標準！\\n【詞義訓詁】「總文武兼剛柔」：文治大略與軍事武功兼備；「輕合」：輕易衝動交戰；「理、備、果、戒、約」：治理、戒備、果決、慎勝、簡約之大將五德。\\n【統帥學（Generalship）之經典】吳起將「理、備、戒、約」等理性自律品格置於「勇」之上，強調大將是軍隊的戰略大腦而非衝鋒陷陣的敢死隊員。"}},{"id":"wu-zi_ch-4_p-2","chapterId":"wu-zi_ch-4","order":2,"canonicalText":"吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。三軍之眾，百萬之師，志厲青雲，氣若風雷，此氣機也；路狹道險，名山大澤，十人守隘，千人莫過，此地機也；善用間諜，知敵虛實，出其不意，攻其不備，此事機也；陳壘牢固，車騎堅利，士卒勇銳，人百其勇，此力機也。知此四者，乃可為大將矣。」","sentenceIds":["wu-zi_ch-4_p-2_s-1","wu-zi_ch-4_p-2_s-2","wu-zi_ch-4_p-2_s-3","wu-zi_ch-4_p-2_s-4","wu-zi_ch-4_p-2_s-5","wu-zi_ch-4_p-2_s-6","wu-zi_ch-4_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：大凡軍事作戰有四大關鍵樞紐機制（四機）：第一是氣機（心理士氣），第二是地機（地理地形），第三是事機（情報謀略），第四是力機（物質軍力）！三軍成千上萬的將士，百萬之眾的大軍，鬥志凌雲、殺氣如同風雷激盪，這就是氣機；\\n道路狹窄地勢險峻，名山大澤阻隔其間，十個人扼守關隘、一千人也無法通過，這就是地機；\\n善於派遣間諜刺探軍情，深知敵軍虛實動向，出其不意攻其不備，這就是事機；\\n營壘柵欄堅固無比，戰車戰馬精良鋒利，士卒訓練有素英勇果敢，一人可當百人之勇，這就是力機！能夠通曉並靈活掌控這四大機制的統帥，才能夠勝任全軍大將！","analysis":"【題解與背景】\\n本段選自《吳子》〈論將〉第 22 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰凡兵有四機一曰氣機二曰地機三曰事機四曰……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「吳」、「子」、「凡」、「兵」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wu-zi_ch-4_p-3","chapterId":"wu-zi_ch-4","order":3,"canonicalText":"吳子曰：「夫將者，三軍之司命，國家之安危也。將不嚴，則三軍憒；將不明，則士卒疑；將不勇，則三軍餒；將不仁，則士卒怨；將不智，則軍事敗。故求將之道，必審其德，察其材，試其能，然後授之以柄。」","sentenceIds":["wu-zi_ch-4_p-3_s-1","wu-zi_ch-4_p-3_s-2","wu-zi_ch-4_p-3_s-3","wu-zi_ch-4_p-3_s-4","wu-zi_ch-4_p-3_s-5","wu-zi_ch-4_p-3_s-6","wu-zi_ch-4_p-3_s-7","wu-zi_ch-4_p-3_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於吳子曰的情境，應當採取相應的具體對策，對於夫鼙鼓金的情境，應當採取相應的具體對策，對於所以威耳的情境，應當採取相應的具體對策，對於旌旗麾幟的情境，應當採取相應的具體對策，對於所以威目的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈論將〉第 23 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰夫將者三軍之司命國家之安危也將不嚴……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「吳」、「子」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-4_p-3）。"}},{"id":"wu-zi_ch-4_p-4","chapterId":"wu-zi_ch-4","order":4,"canonicalText":"吳子曰：「將有三勝：一曰得道，二曰得地，三曰得人。得道者，令行而民樂；得地者，居高而向陽；得人者，士卒勇而將帥和。兼此三者，天下莫能當也。」","sentenceIds":["wu-zi_ch-4_p-4_s-1","wu-zi_ch-4_p-4_s-2","wu-zi_ch-4_p-4_s-3","wu-zi_ch-4_p-4_s-4","wu-zi_ch-4_p-4_s-5","wu-zi_ch-4_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：名將統軍具備三大必勝優勢：第一是得道（得政治之道），第二是得地（得地理優勢），第三是得人（得人和人心）！得到政治之道的人，號令推行而百姓由衷欣樂擁戴；\\n得到地理優勢的人，紮營居於制高點而面向陽光朝向；\\n得到人心和睦的人，士卒作戰勇猛而將帥上下同心和睦！若能同時兼備這三種必勝條件，全天下就再也沒有任何強敵能夠抵擋了！","analysis":"【題解與背景】\\n本段選自《吳子》〈論將〉第 24 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「吳子曰將有三勝一曰得道二曰得地三曰得人得道者……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「吳」、「子」、「將」、「有」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wu-zi_ch-4_p-5","chapterId":"wu-zi_ch-4","order":5,"canonicalText":"吳子曰：「夫受命之日，忘其家；臨軍之日，忘其親；援枹鼓之急，忘其身。如此者，乃可謂之國士，可謂之良將也。」","sentenceIds":["wu-zi_ch-4_p-5_s-1","wu-zi_ch-4_p-5_s-2","wu-zi_ch-4_p-5_s-3","wu-zi_ch-4_p-5_s-4","wu-zi_ch-4_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：身為大將，在接受君主出征任命的那一天，就要忘記自己個人的小家利益；在親臨前線率軍對陣的那一天，就要忘記自己骨肉親人的私情牽掛；在親自手握鼓槌敲響戰鼓衝鋒的緊急關頭，就要徹底忘記自己的個人安危生死！唯有能夠做到這三種至高境界的人，才配稱得上是國家的無雙國士，才配稱得上是名垂青史的棟樑良將！","analysis":"【題解與良將三忘忘家忘親忘身】本段為古代軍人武德與愛國奉獻精神之最高讚歌——受命忘家、臨軍忘親、援枹忘身，千古傳頌！\\n【詞義訓詁】「受命之日忘其家」：以國為家，置國家利益於個人之上；「援枹鼓」：枹，音俘，鼓槌；親執鼓槌擊鼓催陣；「國士良將」：國之棟樑。\\n【軍人犧牲精神之巔峰】此「三忘」境界將軍人的職業倫理提升至神聖的奉獻高度，成為後世岳飛、戚繼光等無數民族英雄立身報國之座右銘。"}},{"id":"wu-zi_ch-5_p-1","chapterId":"wu-zi_ch-5","order":1,"canonicalText":"武侯問曰：「嚴刑峻法，不足以止盜；重賞厚祿，不足以勸戰。為之奈何？」起對曰：「君之賞罰，非不信也，然民未知其貴也。君若使戰勝之士，上堂飲酒，父老妻兒受爵於庭；戰死之士，祠之於廟，撫其孤寡；逃奔之士，恥之於市，不齒於鄉。如此，則民爭勇赴敵矣。」","sentenceIds":["wu-zi_ch-5_p-1_s-1","wu-zi_ch-5_p-1_s-2","wu-zi_ch-5_p-1_s-3","wu-zi_ch-5_p-1_s-4","wu-zi_ch-5_p-1_s-5","wu-zi_ch-5_p-1_s-6","wu-zi_ch-5_p-1_s-7","wu-zi_ch-5_p-1_s-8","wu-zi_ch-5_p-1_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯詢問道：朝廷推行嚴刑峻法，依然不足以禁絕盜賊奸宄；設立重賞厚祿，依然不足以激勵百姓奮勇作戰。面對這種情況該怎麼辦呢？吳起回答說：主君的賞罰制度並非沒有信譽，然而百姓尚未真正體會到這份榮譽的崇高可貴！主君如果能做到：讓作戰立功打勝仗的勇士，登上朝廷大堂與主君同席飲酒，其父母妻兒在宗廟庭堂上接受國家冊封的爵位；讓為國戰死的烈士，在國家宗廟中立碑祭祀，由官府出資撫養其孤兒寡母；讓臨陣脫逃的怯懦者，在市集廣場上公開示眾蒙羞，在鄉里鄉親中被徹底剝奪齒列名分不與為伍！如果能做到這樣，那麼全體百姓必定會爭先恐後勇猛奔赴敵陣殺敵立功了！","analysis":"【題解與榮譽機制與恥感文化激勵】吳起提出超越單純物質賞罰的「社會榮譽機制與恥感文化」——立功者登堂受爵、戰死者入廟撫孤、逃跑者恥於市鄉，徹底激發全民尚武死戰之心！\\n【詞義訓詁】「上堂飲酒」：君臣同席之至高政治榮譽；「祠之於廟」：國家烈士祭祀撫恤制度；「恥之於市，不齒於鄉」：社會性剝奪榮譽與人格羞辱。\\n【激勵機制之現代升華】吳起深刻洞悉人性：物質金錢獎勵有其邊際效用遞減，唯有將國家榮譽、宗族地位與社會認同緊密結合，才能激發出超越生死的強大精神動力。"}},{"id":"wu-zi_ch-5_p-2","chapterId":"wu-zi_ch-5","order":2,"canonicalText":"武侯問曰：「敵若大至，逼我城下，內無積聚，外無強援，將何以禦之？」起對曰：「城固而守，令民無恐。出奇兵以擾其餉道，分精銳以夜襲其營。敵雖大至，遠來必疲，糧道若絕，其軍自潰。此所謂以逸待勞，以奇制眾也。」","sentenceIds":["wu-zi_ch-5_p-2_s-1","wu-zi_ch-5_p-2_s-2","wu-zi_ch-5_p-2_s-3","wu-zi_ch-5_p-2_s-4","wu-zi_ch-5_p-2_s-5","wu-zi_ch-5_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯詢問道：如果強大敵軍大舉壓境，直接兵臨逼近我城池之下，而我城中內部沒有充足的糧草積蓄，外部又沒有強大的援軍解圍，將用什麼辦法來抵禦強敵呢？吳起回答說：首先依托堅固城防堅決固守，穩定民心讓全城百姓不要恐慌。隨後派遣精銳奇兵暗中出城切斷騷擾敵軍的運糧補給線，抽調敢死敢戰精銳部隊在深夜突襲敵軍大營！敵軍雖然人數眾多大舉前來，但長途遠道奔波必定極其疲憊；一旦其後方糧道被我軍截斷，其軍隊內部必定不攻自破自相崩潰！這就是所謂的以逸待勞、以出其不意的奇兵制服人多勢眾之敵的妙法！","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 27 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰敵若大至逼我城下內無積聚外無強援……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-5_p-2）。"}},{"id":"wu-zi_ch-5_p-3","chapterId":"wu-zi_ch-5","order":3,"canonicalText":"武侯問曰：「遇敵於隘，進退不可，為之奈何？」起對曰：「林木險隘，巧用火攻；草澤深阻，分伏奇兵。先發弩以亂其前，後發銳以衝其後。敵不知我之多少，必自潰散矣。」","sentenceIds":["wu-zi_ch-5_p-3_s-1","wu-zi_ch-5_p-3_s-2","wu-zi_ch-5_p-3_s-3","wu-zi_ch-5_p-3_s-4","wu-zi_ch-5_p-3_s-5","wu-zi_ch-5_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯問道：如果我們在狹窄險要的地方遇到敵人，前進和後退都不可能，該怎麼辦？吳起回答說：如果是在樹林茂密、地勢險峻的狹窄處，就要巧妙地運用火攻；如果是在雜草叢生、沼澤深陷的阻絕地帶，就要分散埋伏奇兵。作戰時，先發射強弩來擾亂敵軍的前鋒，然後派出精銳部隊去衝擊敵軍的後方。敵人摸不清我們到底有多少兵力，必然會自己潰敗散亂。","analysis":"【訓詁與名物】「隘」指狹窄險要的地形。「草澤深阻」指水草叢生的泥濘窪地，行軍困難。「奇兵」指隱蔽埋伏、出其不意攻擊敵人的部隊。「弩」是古代一種利用機械力量射箭的遠射兵器。「銳」指精銳部隊。\\n【章法與結構】本段採取兵書常見的一問一答形式，條理清晰。吳起的回答分為兩層：第一層針對「林木」與「草澤」兩種不同的險隘地形，分別提出「火攻」與「伏兵」的戰術原則；第二層則指示具體的戰鬥步驟，即「先亂其前，後衝其後」，最後點出戰術目的：製造心理恐慌，使敵軍自潰。\\n【思想與義理】此段反映了《吳子》兵法中「因地制宜」與「攻心為上」的軍事思想。在絕境中，不應盲目硬拚，而要善用自然環境（火與地形）來彌補自身的劣勢。同時，透過前後夾擊與奇兵埋伏，在心理上給予敵人未知與恐懼，達到「不戰而潰」的最佳效果，展現了高超的戰術心理學。"}},{"id":"wu-zi_ch-5_p-4","chapterId":"wu-zi_ch-5","order":4,"canonicalText":"武侯問曰：「大水氾濫，車騎不便，士卒阻溺，為之奈何？」起對曰：「避高就燥，作舟楫以通之；築浮橋以濟之。順流而放火，乘風而進戰。敵居下流，必受其害。」","sentenceIds":["wu-zi_ch-5_p-4_s-1","wu-zi_ch-5_p-4_s-2","wu-zi_ch-5_p-4_s-3","wu-zi_ch-5_p-4_s-4","wu-zi_ch-5_p-4_s-5","wu-zi_ch-5_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於武侯問曰的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於欲去無路的情境，應當採取相應的具體對策，對於我眾甚懼的情境，應當採取相應的具體對策，對於為之柰何的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 29 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰大水氾濫車騎不便士卒阻溺為之奈何……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-5_p-4）。"}},{"id":"wu-zi_ch-5_p-5","chapterId":"wu-zi_ch-5","order":5,"canonicalText":"武侯問曰：「大風暴雨，晝夜不息，旌旗摧折，人馬驚駭，為之奈何？」起對曰：「風雨者，天之威也。順風而呼，聲非加疾也，而聞者彰；順風而發，矢非加疾也，而及者遠。故順風而擊，借天威以破敵，雖有百萬，可勝也。」","sentenceIds":["wu-zi_ch-5_p-5_s-1","wu-zi_ch-5_p-5_s-2","wu-zi_ch-5_p-5_s-3","wu-zi_ch-5_p-5_s-4","wu-zi_ch-5_p-5_s-5","wu-zi_ch-5_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於武侯問曰的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於傍多險阻的情境，應當採取相應的具體對策，對於彼眾我寡的情境，應當採取相應的具體對策，對於為之奈何的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 30 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰大風暴雨晝夜不息旌旗摧折人馬驚駭……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-5_p-5）。"}},{"id":"wu-zi_ch-5_p-6","chapterId":"wu-zi_ch-5","order":6,"canonicalText":"武侯問曰：「敵若堅壘不出，野無所掠，軍糧將盡，為之奈何？」起對曰：「佯退以誘其出，示弱以驕其心。設伏於要道，分兵以擊其虛。敵見我退，必出追之，伏兵發而其軍破矣。」","sentenceIds":["wu-zi_ch-5_p-6_s-1","wu-zi_ch-5_p-6_s-2","wu-zi_ch-5_p-6_s-3","wu-zi_ch-5_p-6_s-4","wu-zi_ch-5_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於武侯問曰的情境，應當採取相應的具體對策，對於左右高山的情境，應當採取相應的具體對策，對於地甚狹迫的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於擊之不敢的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 31 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰敵若堅壘不出野無所掠軍糧將盡為之……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-5_p-6）。"}},{"id":"wu-zi_ch-5_p-7","chapterId":"wu-zi_ch-5","order":7,"canonicalText":"武侯問曰：「暴師經年，士卒疲憊，物資匱乏，將何以安之？」起對曰：「寬其徭役，撫其家室；厚其賞賜，省其刑罰。將帥同其甘苦，身在行伍之中。士卒見將帥之苦，則忘其勞矣。」","sentenceIds":["wu-zi_ch-5_p-7_s-1","wu-zi_ch-5_p-7_s-2","wu-zi_ch-5_p-7_s-3","wu-zi_ch-5_p-7_s-4","wu-zi_ch-5_p-7_s-5","wu-zi_ch-5_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯詢問道：如果大軍長年在外征戰（暴師經年），士卒身心極度疲憊，國家財政物資日漸匱乏，將用什麼辦法來安撫軍心穩定局勢呢？吳起回答說：應當寬減國內百姓的徭役負擔，妥善撫恤優待前線將士的家室老小；加大戰功的賞賜標準，精簡寬免嚴苛的軍紀刑罰。最關鍵的是統帥將帥必須親身同全體將士同甘共苦，起居作息親身在普通士卒行伍之中！廣大士兵親眼看見統帥將軍與自己承受同樣的艱難困苦，就會由衷忘記自身的疲勞與怨恨了！","analysis":"【題解與將帥同甘共苦以安疲軍】吳起以身作則的統帥哲學——將帥同甘共苦（吮疽之仁、身在行伍），以真誠仁愛化解長年征戰將士之怨氣與疲憊。\\n【詞義訓詁】「暴師經年」：大軍長年在外風餐露宿征戰；「將帥同其甘苦」：吳起行軍與士卒同衣同食、不乘車馬、親自負糧。\\n【同甘共苦之感染力】《史記・孫子吳起列傳》載吳起為病卒親口吮疽。統帥以身作則、同甘共苦，能產生無與倫比的感召力，使全軍視死如歸。"}},{"id":"wu-zi_ch-5_p-8","chapterId":"wu-zi_ch-5","order":8,"canonicalText":"武侯問曰：「敵若以奇勝我，為之奈何？」起對曰：「奇正相生，循環無窮。敵以奇來，我以正待之；敵以正來，我以奇應之。審察其變，動不失時，則奇不得神矣。」","sentenceIds":["wu-zi_ch-5_p-8_s-1","wu-zi_ch-5_p-8_s-2","wu-zi_ch-5_p-8_s-3","wu-zi_ch-5_p-8_s-4","wu-zi_ch-5_p-8_s-5","wu-zi_ch-5_p-8_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯問道：如果敵人用奇兵戰勝了我們，該怎麼辦？吳起回答說：奇兵和正規軍是相互轉化、循環無窮的。敵人如果用奇兵來進攻，我們就用正規的陣法來嚴陣以待；敵人如果用正規軍來進攻，我們就用奇兵去應對。仔細觀察敵軍陣型的變化，行動時不要錯失良機，那麼敵人的奇兵就無法發揮神奇的功效了。","analysis":"【訓詁與名物】「奇」讀音為ㄐㄧ，指常規之外、出其不意的兵力或戰術。「正」指常規的、正面的部隊與陣法。「奇正相生」意指奇與正可以相互轉化，無窮無盡。「神」在這裡作動詞用，指發揮神奇難測的功效。\\n【章法與結構】本段依舊是一問一答，但吳起的回答深具辯證色彩。首句「奇正相生，循環無窮」是全段的總綱；接著以「敵以奇來，我以正待之」等兩句進行具體的對仗說明，提出應對策略；最後以「審察其變」點出落實策略的關鍵條件，邏輯嚴密，層次分明。\\n【思想與義理】此段文字揭示了中國古代兵法中極為重要的「奇正」哲學。吳子認為戰場上沒有絕對的「奇」或「正」，兩者是相對且動態轉換的。面對敵人的變化，統帥必須具備冷靜的洞察力（審察其變）與精準的決斷力（動不失時），以不變應萬變，或以萬變應不變，這不僅是軍事戰術，更是深刻的辯證思想。"}},{"id":"wu-zi_ch-5_p-9","chapterId":"wu-zi_ch-5","order":9,"canonicalText":"武侯問曰：「兩軍相遇，未知彼己之強弱，為之奈何？」起對曰：「遣輕騎以試之，薄其前以觀其動。動而整者，不可輕擊；動而亂者，可乘而破。此試敵之法也。」","sentenceIds":["wu-zi_ch-5_p-9_s-1","wu-zi_ch-5_p-9_s-2","wu-zi_ch-5_p-9_s-3","wu-zi_ch-5_p-9_s-4","wu-zi_ch-5_p-9_s-5","wu-zi_ch-5_p-9_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於武侯問曰的情境，應當採取相應的具體對策，對於暴寇卒來的情境，應當採取相應的具體對策，對於掠吾田野的情境，應當採取相應的具體對策，對於取吾牛羊的情境，應當採取相應的具體對策，對於則如之何的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 34 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰兩軍相遇未知彼己之強弱為之奈何起……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-5_p-9）。"}},{"id":"wu-zi_ch-5_p-10","chapterId":"wu-zi_ch-5","order":10,"canonicalText":"武侯問曰：「敵若遠來，糧餉不繼，而軍容甚盛，為之奈何？」起對曰：「此其虛張聲勢也。深溝高壘以持久，設奇以斷其後。不出旬日，其軍自乏，乏則必退，退而擊之，可得全勝。」","sentenceIds":["wu-zi_ch-5_p-10_s-1","wu-zi_ch-5_p-10_s-2","wu-zi_ch-5_p-10_s-3","wu-zi_ch-5_p-10_s-4","wu-zi_ch-5_p-10_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於起對曰的情境，應當採取相應的具體對策，對於暴寇之來的情境，應當採取相應的具體對策，對於必慮其強的情境，應當採取相應的具體對策，對於善守勿應的情境，應當採取相應的具體對策，對於彼將暮去的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 35 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰敵若遠來糧餉不繼而軍容甚盛為之奈……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-5_p-10）。"}},{"id":"wu-zi_ch-5_p-11","chapterId":"wu-zi_ch-5","order":11,"canonicalText":"武侯問曰：「敵若乘勝逐北，我軍挫敗，將何以救之？」起對曰：「收散卒以固後陳，設伏兵以斷其追。將帥親自斷後，激勵士卒以必死之志。敵見我有備，追必不深；乘其怠而反擊，敗可復勝也。」","sentenceIds":["wu-zi_ch-5_p-11_s-1","wu-zi_ch-5_p-11_s-2","wu-zi_ch-5_p-11_s-3","wu-zi_ch-5_p-11_s-4","wu-zi_ch-5_p-11_s-5","wu-zi_ch-5_p-11_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯詢問道：如果敵軍剛剛打了勝仗正乘勝兇猛追擊敗兵（逐北），我軍初戰受挫陷入敗局，將用什麼辦法來挽救危局呢？吳起回答說：應當迅速收攏潰散的殘兵士卒以鞏固後方重整陣容，在要道險隘設下精銳伏兵以阻斷阻截敵軍的瘋狂追兵！主將統帥親自率領親兵殿後掩護，以視死如歸的必死鬥志激勵全體官兵奮勇抵抗！敵軍看見我軍撤退井然有備、伏兵齊全，其追擊必定不敢過於深入孤軍冒進；此時我軍趁其追兵疲憊懈怠之機驟然發動反擊，原本的敗局就能奇蹟般轉敗為勝了！","analysis":"【題解與背景】\\n本段選自《吳子》〈應變〉第 36 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰敵若乘勝逐北我軍挫敗將何以救之起對曰……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「武」、「侯」、「問」、「敵」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wu-zi_ch-6_p-1","chapterId":"wu-zi_ch-6","order":1,"canonicalText":"武侯問曰：「嚴刑峻法，不足以止盜；重賞厚祿，不足以勸戰。為之奈何？」起對曰：「君之賞罰，非不信也，然民未知其貴也。昔者明王勵士，設宴於堂，論功行賞，使有功者顯於天下，無功者恥於閭里。如此，則民爭勇赴敵矣。」","sentenceIds":["wu-zi_ch-6_p-1_s-1","wu-zi_ch-6_p-1_s-2","wu-zi_ch-6_p-1_s-3","wu-zi_ch-6_p-1_s-4","wu-zi_ch-6_p-1_s-5","wu-zi_ch-6_p-1_s-6","wu-zi_ch-6_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於武侯問曰的情境，應當採取相應的具體對策，必須建立明確的賞罰與法度，對於足以勝乎的情境，應當採取相應的具體對策，對於起對曰的情境，應當採取相應的具體對策，對於嚴明之事的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈勵士〉第 37 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯問曰嚴刑峻法不足以止盜重賞厚祿不足以……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「問」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-6_p-1）。"}},{"id":"wu-zi_ch-6_p-2","chapterId":"wu-zi_ch-6","order":2,"canonicalText":"武侯乃設宴於堂，坐功臣於前，賜以重器；次功者坐於中，賜以精器；無功者坐於後，食而不賜。又厚撫其父母妻子。於是魏國之士，莫不爭死。","sentenceIds":["wu-zi_ch-6_p-2_s-1","wu-zi_ch-6_p-2_s-2","wu-zi_ch-6_p-2_s-3","wu-zi_ch-6_p-2_s-4","wu-zi_ch-6_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於武侯曰的情境，應當採取相應的具體對策，對於致之奈何的情境，應當採取相應的具體對策，對於對曰的情境，應當採取相應的具體對策，領導者應具備深遠的眼光與美德，對於無功而勵的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《吳子》〈勵士〉第 38 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯乃設宴於堂坐功臣於前賜以重器次功者坐……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「乃」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-6_p-2）。"}},{"id":"wu-zi_ch-6_p-3","chapterId":"wu-zi_ch-6","order":3,"canonicalText":"兼年，秦興師臨陰晉，魏氏之兵莫不請戰。起請以五萬之眾破之。武侯曰：「秦軍五十萬，子以五萬，奈何？」起曰：「臣之所教五萬人，皆勇銳之士，一人當百。且士卒皆以死為榮，以退為恥，此必勝之勢也。」","sentenceIds":["wu-zi_ch-6_p-3_s-1","wu-zi_ch-6_p-3_s-2","wu-zi_ch-6_p-3_s-3","wu-zi_ch-6_p-3_s-4","wu-zi_ch-6_p-3_s-5","wu-zi_ch-6_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"到了第二年，秦國傾全國之兵五十萬大軍大舉進攻魏國重鎮陰晉，魏國全體將士百姓群情激憤、人人主動請求出征參戰！吳起向魏武侯請求僅率領五萬魏國部隊前往迎敵破敵。魏武侯驚訝地說：秦軍有五十萬之眾，先生僅帶五萬人去，如何能打得贏呢？吳起回答說：臣平日所訓練調教的這五萬名魏武卒，全都是精挑細選的勇銳之士，各個都能以一當百！況且全體將士皆將為國死戰視為至高榮耀，將畏縮潰退視為莫大恥辱，這在戰鬥精神上已經是必勝的壓倒性優勢了！","analysis":"【題解與陰晉之戰五萬破五十萬之序幕】本段記錄中國歷史上最著名的以少勝多戰役之一——公元前389年「陰晉之戰」，吳起率五萬魏武卒對陣五十萬秦軍的戰前對話！\\n【詞義訓詁】「陰晉」：戰國魏國河西重鎮（今陝西華陰東）；「五萬破五十萬」：十倍兵力懸殊之傳奇決戰；「魏武卒」：吳起親手創建的戰國最強重裝步兵軍團。\\n【魏武卒神話】吳起訓練的魏武卒身披重鎧、手執長戟、腰佩利劍、背負強弩與五十支箭、攜帶三日口糧，日行百里，是中國歷史上最早的特種職業軍人體系。"}},{"id":"wu-zi_ch-6_p-4","chapterId":"wu-zi_ch-6","order":4,"canonicalText":"起乃率車五百乘，騎三千匹，步卒五萬，與秦戰於陰晉。三軍之士，見敵若仇，爭勇先登，大破秦軍五十萬之眾。天下莫不震服。","sentenceIds":["wu-zi_ch-6_p-4_s-1","wu-zi_ch-6_p-4_s-2","wu-zi_ch-6_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起於是統率戰車五百輛、精銳騎兵三千匹、重裝步兵五萬人，在陰晉平原與秦軍展開歷史性大決戰！魏國三軍全體將士見到敵軍如同見到宿世仇敵般奮勇爭先，人人爭搶著身先士卒勇登陷陣，一舉將秦國五十萬大軍徹底擊潰殲滅！天下所有諸侯列國無不為之震驚敬服！","analysis":"【題解與陰晉大捷殲敵五十萬震服天下】吳起以步騎車協同作戰，率五萬魏武卒大破秦軍五十萬，收復整個河西之地，確立魏國戰國初期天下第一霸主地位！\\n【詞義訓詁】「車五百乘騎三千步卒五萬」：步車騎立體化合成作戰編制；「見敵若仇」：士氣昂揚至極點；「天下震服」：威震天下。\\n【戰史奇蹟】陰晉之戰創造了華夏古代戰爭史上以少勝多、兵力對比最為懸殊的輝煌戰例，證明了吳起「治兵、勵士、精兵」思想的極致威力。"}},{"id":"wu-zi_ch-6_p-5","chapterId":"wu-zi_ch-6","order":5,"canonicalText":"吳子曰：「夫戰勝攻取，非難也；守勝固功，難也。故明君勝而不驕，勇而不暴。賞罰以信，恩威並用，則士卒死義，雖有強敵，何足懼哉！」","sentenceIds":["wu-zi_ch-6_p-5_s-1","wu-zi_ch-6_p-5_s-2","wu-zi_ch-6_p-5_s-3","wu-zi_ch-6_p-5_s-4","wu-zi_ch-6_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"吳起說：在戰場上打勝仗、攻取敵人的陣地，這並不是最困難的；要在勝利後守住成果、鞏固功業，這才是最困難的。所以聖明的君主在勝利後不會驕傲，勇敢卻不會粗暴。賞罰講求誠信，恩惠與威嚴同時並用，那麼士兵就會為了道義而拼死作戰，即使遇到強大的敵人，又有什麼好害怕的呢！","analysis":"【訓詁與名物】「攻取」指攻佔敵方城池或陣地。「守勝固功」意指保全勝利的果實並鞏固已建立的功業。「信」在這裡是誠信、言出必行的意思。「死義」指為正義或恩義而拼死效命。\\n【章法與結構】本段採用了先破後立、對比論證的手法。首句以「非難也」與「難也」的強烈對比，點出守成不易的千古難題。接著從君主的個人修養（勝而不驕，勇而不暴）與統御手段（賞罰以信，恩威並用）兩個層次提出解決之道，最後以反問句「何足懼哉」作結，氣勢磅礴。\\n【思想與義理】這段話體現了《吳子》兵法超越純粹戰術層面的戰略與政治眼光。吳起深刻地認識到，軍事上的勝利只是暫時的，真正的考驗在於戰後的政治治理與人心向背。唯有領導者具備高尚的品德修養，並以誠信恩威統御軍隊，才能凝聚無堅不摧的戰鬥力，這與儒家「仁者無敵」的思想有著異曲同工之妙。"}},{"id":"wu-zi_ch-6_p-6","chapterId":"wu-zi_ch-6","order":6,"canonicalText":"武侯大悅，遂命吳起治西河。起在西河，名震諸侯，魏國以霸。此勵士治兵之大效也。","sentenceIds":["wu-zi_ch-6_p-6_s-1","wu-zi_ch-6_p-6_s-2","wu-zi_ch-6_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"},{"label":"維基文庫《吳子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%90%B3%E5%AD%90"}],"readingAid":{"translation":"魏武侯無比高興欣悅，隨即正式任命吳起為西河郡守，全面總攬鎮守西河軍政大權。吳起在西河任職期間，威名震動天下諸侯列國，向西壓制強秦不敢東向，輔佐魏國成就了中原霸業。這正是精研勵士之策、嚴明治兵大道的偉大成效啊！","analysis":"【題解與背景】\\n本段選自《吳子》〈勵士〉第 42 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「武侯大悅遂命吳起治西河起在西河名震諸侯魏……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「武」、「侯」、「大」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《吳子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wu-zi_ch-6_p-6）。"}}],"sentences":[{"id":"wu-zi_ch-1_p-5_s-1","passageId":"wu-zi_ch-1_p-5","order":1,"canonicalText":"吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。","chunks":[["吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-2","passageId":"wu-zi_ch-1_p-5","order":2,"canonicalText":"其名又有五：一曰義兵，二曰強兵，三曰剛兵，四曰暴兵，五曰逆兵。","chunks":[["其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-3","passageId":"wu-zi_ch-1_p-5","order":3,"canonicalText":"禁暴救亂曰義，恃眾伐寡曰強，因怒興師曰剛，棄禮貪利曰暴，國亂人疲而舉事曰逆。","chunks":[["禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-4","passageId":"wu-zi_ch-1_p-5","order":4,"canonicalText":"五者之服，各有其道：義必以禮服，強必以謙服，剛必以辭服，暴必以詐服，逆必以權服。","chunks":[["五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-5","passageId":"wu-zi_ch-1_p-5","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-1","passageId":"wu-zi_ch-1_p-7","order":1,"canonicalText":"武侯問曰：「願聞陳必定、守必固、戰必勝之道。","chunks":[["武侯問曰：「願聞陳必定、守必固、戰必勝之道。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-2","passageId":"wu-zi_ch-1_p-7","order":2,"canonicalText":"」起對曰：「立見且可，豈直聞乎！","chunks":[["」起對曰：「立見且可，豈直聞乎！","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-3","passageId":"wu-zi_ch-1_p-7","order":3,"canonicalText":"君能使賢者居上，不肖者居下，則陳已定矣；","chunks":[["君能使賢者居上，不肖者處下，則陳已定矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-4","passageId":"wu-zi_ch-1_p-7","order":4,"canonicalText":"民安其田宅，親其官長，則守已固矣；","chunks":[["民安其田宅，親其有司，則守已固矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-5","passageId":"wu-zi_ch-1_p-7","order":5,"canonicalText":"百姓皆是吾君而非鄰國，則戰已勝矣。","chunks":[["百姓皆是吾君而非鄰國，則戰已勝矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-6","passageId":"wu-zi_ch-1_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-1","passageId":"wu-zi_ch-1_p-8","order":1,"canonicalText":"武侯嘗謀事，群臣莫能及，罷朝而有喜色。","chunks":[["武侯嘗謀事，群臣莫能及，罷朝而有喜色。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-2","passageId":"wu-zi_ch-1_p-8","order":2,"canonicalText":"起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。","chunks":[["起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-3","passageId":"wu-zi_ch-1_p-8","order":3,"canonicalText":"申公巫臣問曰：『君何為有憂色？","chunks":[["申公問曰：『君有憂色，何也？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-4","passageId":"wu-zi_ch-1_p-8","order":4,"canonicalText":"』莊王曰：『諸侯自以為不及人者，乃能得師。","chunks":[["』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-5","passageId":"wu-zi_ch-1_p-8","order":5,"canonicalText":"今群臣莫及寡人，楚國其殆矣！","chunks":[["今寡人不才，而群臣莫及者，楚國其殆矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-6","passageId":"wu-zi_ch-1_p-8","order":6,"canonicalText":"』此楚莊王之所以憂，而君反以為喜，臣是以懼也。","chunks":[["』此楚莊王之所憂，而君說之，臣竊懼矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-7","passageId":"wu-zi_ch-1_p-8","order":7,"canonicalText":"」武侯慚。","chunks":[["」於是武侯有慚色。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-1","passageId":"wu-zi_ch-3_p-6","order":1,"canonicalText":"吳子曰：「夫教人以戰，如教童子。","chunks":[["吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-2","passageId":"wu-zi_ch-3_p-6","order":2,"canonicalText":"以一人教十人，十人教百人，百人教千人，千人教萬人，萬人教三軍。","chunks":[["鄉里相比，什伍相保。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-3","passageId":"wu-zi_ch-3_p-6","order":3,"canonicalText":"教之以坐作進退，習之以疾徐俯仰，練之以合散聚分。","chunks":[["一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-4","passageId":"wu-zi_ch-3_p-6","order":4,"canonicalText":"日日操之，歲歲習之，則民皆精熟，臨戰不惑矣。","chunks":[["聞鼓聲合，然後舉旗。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-5","passageId":"wu-zi_ch-3_p-6","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-1","passageId":"wu-zi_ch-4_p-5","order":1,"canonicalText":"吳子曰：「夫受命之日，忘其家；","chunks":[["武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-2","passageId":"wu-zi_ch-4_p-5","order":2,"canonicalText":"臨軍之日，忘其親；","chunks":[["」起對曰：「令賤而勇者，將輕銳以嘗之。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-3","passageId":"wu-zi_ch-4_p-5","order":3,"canonicalText":"援枹鼓之急，忘其身。","chunks":[["務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-4","passageId":"wu-zi_ch-4_p-5","order":4,"canonicalText":"如此者，乃可謂之國士，可謂之良將也。","chunks":[["若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-5","passageId":"wu-zi_ch-4_p-5","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-1","passageId":"wu-zi_ch-5_p-5","order":1,"canonicalText":"武侯問曰：「大風暴雨，晝夜不息，旌旗摧折，人馬驚駭，為之奈何？","chunks":[["武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-2","passageId":"wu-zi_ch-5_p-5","order":2,"canonicalText":"」起對曰：「風雨者，天之威也。","chunks":[["」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-3","passageId":"wu-zi_ch-5_p-5","order":3,"canonicalText":"順風而呼，聲非加疾也，而聞者彰；","chunks":[["若高山深谷，卒然相遇，必先鼓譟而乘之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-4","passageId":"wu-zi_ch-5_p-5","order":4,"canonicalText":"順風而發，矢非加疾也，而及者遠。","chunks":[["進弓與弩，且射且虜。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-5","passageId":"wu-zi_ch-5_p-5","order":5,"canonicalText":"故順風而擊，借天威以破敵，雖有百萬，可勝也。","chunks":[["審察其政，亂則擊之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-6","passageId":"wu-zi_ch-5_p-5","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-1","passageId":"wu-zi_ch-5_p-7","order":1,"canonicalText":"武侯問曰：「暴師經年，士卒疲憊，物資匱乏，將何以安之？","chunks":[["武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-2","passageId":"wu-zi_ch-5_p-7","order":2,"canonicalText":"」起對曰：「寬其徭役，撫其家室；","chunks":[["」起對曰：「此謂水戰，無用車騎，且留其傍。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-3","passageId":"wu-zi_ch-5_p-7","order":3,"canonicalText":"厚其賞賜，省其刑罰。","chunks":[["登高四望，必得水情。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-4","passageId":"wu-zi_ch-5_p-7","order":4,"canonicalText":"將帥同其甘苦，身在行伍之中。","chunks":[["知其廣狹，盡其淺深，乃可為奇以勝之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-5","passageId":"wu-zi_ch-5_p-7","order":5,"canonicalText":"士卒見將帥之苦，則忘其勞矣。","chunks":[["敵若絕水，半渡而薄之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-6","passageId":"wu-zi_ch-5_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-1","passageId":"wu-zi_ch-5_p-8","order":1,"canonicalText":"武侯問曰：「敵若以奇勝我，為之奈何？","chunks":[["武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-2","passageId":"wu-zi_ch-5_p-8","order":2,"canonicalText":"」起對曰：「奇正相生，循環無窮。","chunks":[["」起對曰：「凡用車者，陰濕則停，陽燥則起；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-3","passageId":"wu-zi_ch-5_p-8","order":3,"canonicalText":"敵以奇來，我以正待之；","chunks":[["貴高賤下，馳其強車；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-4","passageId":"wu-zi_ch-5_p-8","order":4,"canonicalText":"敵以正來，我以奇應之。","chunks":[["若進若止，必從其道。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-5","passageId":"wu-zi_ch-5_p-8","order":5,"canonicalText":"審察其變，動不失時，則奇不得神矣。","chunks":[["敵人若起，必逐其跡。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-6","passageId":"wu-zi_ch-5_p-8","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-1","passageId":"wu-zi_ch-6_p-6","order":1,"canonicalText":"武侯大悅，遂命吳起治西河。","chunks":[["先戰一日，吳起令三軍曰：「諸吏士當從受馳。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-2","passageId":"wu-zi_ch-6_p-6","order":2,"canonicalText":"起在西河，名震諸侯，魏國以霸。","chunks":[["車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-3","passageId":"wu-zi_ch-6_p-6","order":3,"canonicalText":"此勵士治兵之大效也。","chunks":[["」故戰之日，其令不煩而威震天下。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-1","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":1,"canonicalText":"吳起儒服以兵機見魏文侯。","chunks":[]},{"id":"wu-zi_ch-1_p-1_s-2","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":2,"canonicalText":"文侯曰：「寡人不好軍旅之事。","chunks":[]},{"id":"wu-zi_ch-1_p-1_s-3","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":3,"canonicalText":"」起曰：「臣以見佔隱，以往察來，主君何言與心違。","chunks":[]},{"id":"wu-zi_ch-1_p-1_s-4","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":4,"canonicalText":"今君歲時屠宰，不以肥瘠，飾皮革，朱漆以文，此欲用之，非無用也。","chunks":[]},{"id":"wu-zi_ch-1_p-1_s-5","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":5,"canonicalText":"且君若無兵，雖有智謀，何以衛國？","chunks":[]},{"id":"wu-zi_ch-1_p-1_s-6","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":6,"canonicalText":"文武並用，雄霸之基也。","chunks":[]},{"id":"wu-zi_ch-1_p-1_s-7","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-1","order":7,"canonicalText":"」文侯乃親延之。","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-1","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":1,"canonicalText":"吳子曰：「昔之圖國家者，必先教百姓而親萬民。","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-2","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":2,"canonicalText":"有四不和：不和於國，不可以出軍；","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-3","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":3,"canonicalText":"不和於軍，不可以出陣；","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-4","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":4,"canonicalText":"不和於陣，不可以進戰；","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-5","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":5,"canonicalText":"不和於戰，不可以決勝。","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-6","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":6,"canonicalText":"是以有道之主，將用其民，先和而造大事。","chunks":[]},{"id":"wu-zi_ch-1_p-2_s-7","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-2","order":7,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-1","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":1,"canonicalText":"吳子曰：「夫道者，所以反本復始。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-2","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":2,"canonicalText":"義者，所以行事立功。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-3","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":3,"canonicalText":"謀者，所以違害就利。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-4","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":4,"canonicalText":"要者，所以保業守成。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-5","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":5,"canonicalText":"若行不合道，舉不合義，而處大居貴，患必及之。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-6","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":6,"canonicalText":"是以聖人綏之以道，理之以義，動之以禮，撫之以仁。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-7","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":7,"canonicalText":"此四德者，修之則興，廢之則衰。","chunks":[]},{"id":"wu-zi_ch-1_p-3_s-8","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-3","order":8,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-1","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":1,"canonicalText":"吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-2","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":2,"canonicalText":"夫人有恥，在大足以戰，在小足以守矣。","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-3","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":3,"canonicalText":"服者，所以彰德也；","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-4","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":4,"canonicalText":"鼓角者，所以揚威也；","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-5","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":5,"canonicalText":"刑賞者，所以示威信也。","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-6","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":6,"canonicalText":"故賞不可不信，罰不可不武。","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-7","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":7,"canonicalText":"進有重賞，退有死刑，雖有百萬之眾，如一人焉。","chunks":[]},{"id":"wu-zi_ch-1_p-4_s-8","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-4","order":8,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-1","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":1,"canonicalText":"武侯問曰：「願聞治兵、料人、固國之道。","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-2","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":2,"canonicalText":"」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-3","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":3,"canonicalText":"昔齊桓公九合諸侯，一匡天下，管仲之謀也。","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-4","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":4,"canonicalText":"晉文公出定襄王，踐土之盟，狐偃之功也。","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-5","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":5,"canonicalText":"故得賢者昌，失賢者亡。","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-6","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":6,"canonicalText":"君其務在得人。","chunks":[]},{"id":"wu-zi_ch-1_p-6_s-7","chapterId":"wu-zi_ch-1","passageId":"wu-zi_ch-1_p-6","order":7,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-1","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":1,"canonicalText":"武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-2","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":2,"canonicalText":"六國兵四守，勢甚不便，為之奈何？","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-3","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":3,"canonicalText":"」起對曰：「夫齊性剛，其政猛，民貪而吏輕，故其陳重而不能久，破之必分其兵。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-4","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":4,"canonicalText":"秦性強，其政嚴，民勇而多詐，故其陳散而自為戰，破之必以利誘。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-5","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":5,"canonicalText":"楚性弱，其政亂，民疲而力散，故其陳整而不能守，破之必驚其氣。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-6","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":6,"canonicalText":"趙性平，其政和，民勞而力拙，故其陳固而不能進，破之必薄其前。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-7","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":7,"canonicalText":"燕性慤，其政愚，民慎而無謀，故其陳密而不能動，破之必衝其後。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-8","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":8,"canonicalText":"韓性端，其政定，民疲而少戰，故其陳正而不能奇，破之必乘其隙。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-9","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":9,"canonicalText":"此六國之情也。","chunks":[]},{"id":"wu-zi_ch-2_p-1_s-10","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-1","order":10,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-1","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":1,"canonicalText":"吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-2","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":2,"canonicalText":"二曰盛夏炎熱，晏興無息，行飢渴，千里不絕；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-3","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":3,"canonicalText":"三曰師久淹留，糧草乏絕，百姓怨嗟，妖祥數起；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-4","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":4,"canonicalText":"四曰軍資既竭，薪芻既乏，天雨霖霪，欲取無所；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-5","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":5,"canonicalText":"五曰徒眾不多，水地不便，人馬疲病，四鄰不救；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-6","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":6,"canonicalText":"六曰道遠日暮，士卒勞倦，飢餒未食，解甲而息；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-7","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":7,"canonicalText":"七曰將吏卑弱，士卒不和，動靜無常，三軍易駭；","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-8","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":8,"canonicalText":"八曰陳隊未定，舍壘未成，傾險狹路，半度而擊。","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-9","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":9,"canonicalText":"此八者，擊之必勝，無疑也。","chunks":[]},{"id":"wu-zi_ch-2_p-2_s-10","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-2","order":10,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-1","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":1,"canonicalText":"吳子曰：「凡料敵有不占而避之者六：一曰土地廣大，人民富盛；","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-2","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":2,"canonicalText":"二曰上愛其下，惠施流布；","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-3","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":3,"canonicalText":"三曰賞罰信明，動靜及時；","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-4","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":4,"canonicalText":"四曰陳列勇銳，將明兵精；","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-5","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":5,"canonicalText":"五曰兵革備具，資糧充饒；","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-6","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":6,"canonicalText":"六曰四鄰合從，大國為援。","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-7","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":7,"canonicalText":"凡見此六者，審避之勿疑。","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-8","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":8,"canonicalText":"敵若可進則進，不可進則退，此知兵之大要也。","chunks":[]},{"id":"wu-zi_ch-2_p-3_s-9","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-3","order":9,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-1","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":1,"canonicalText":"武侯問曰：「敵眾我寡，敵強我弱，為之奈何？","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-2","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":2,"canonicalText":"」起對曰：「避之於易，邀之於隘。","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-3","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":3,"canonicalText":"故曰：以一擊十，莫善於隘；","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-4","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":4,"canonicalText":"以十擊百，莫善於險；","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-5","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":5,"canonicalText":"以千擊萬，莫善於阻。","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-6","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":6,"canonicalText":"今有少眾，卒起於深草狹路之中，擊其半渡，斷其後陳，則敵雖眾，亦可破也。","chunks":[]},{"id":"wu-zi_ch-2_p-4_s-7","chapterId":"wu-zi_ch-2","passageId":"wu-zi_ch-2_p-4","order":7,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":1,"canonicalText":"吳子曰：「夫進路退路，乃戰之大端。","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":2,"canonicalText":"凡治兵者，必先教令為先。","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":3,"canonicalText":"教令明，則進退一；","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-4","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":4,"canonicalText":"進退一，則三軍齊。","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-5","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":5,"canonicalText":"三軍齊，則動靜同。","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-6","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":6,"canonicalText":"動靜同，則威武立矣。","chunks":[]},{"id":"wu-zi_ch-3_p-1_s-7","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-1","order":7,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":1,"canonicalText":"吳子曰：「金鼓旌旗，所以肅視聽也。","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":2,"canonicalText":"視旌旗之指而動，聽金鼓之聲而進。","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":3,"canonicalText":"鼓之則進，金之則止；","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-4","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":4,"canonicalText":"麾之則左，旗之則右。","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-5","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":5,"canonicalText":"號令既宣，犯令者誅。","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-6","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":6,"canonicalText":"賞必及時，罰必當罪。","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-7","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":7,"canonicalText":"如此，則三軍之士，見利不敢先，見危不敢退矣。","chunks":[]},{"id":"wu-zi_ch-3_p-2_s-8","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-2","order":8,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-3_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-3","order":1,"canonicalText":"吳子曰：「治兵有三戒：一曰無以重勞擊輕安，二曰無以大飢擊大飽，三曰無以大亂擊大整。","chunks":[]},{"id":"wu-zi_ch-3_p-3_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-3","order":2,"canonicalText":"夫能避其所不能，擊其所能，則萬戰萬勝矣。","chunks":[]},{"id":"wu-zi_ch-3_p-3_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-3","order":3,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-4_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-4","order":1,"canonicalText":"吳子曰：「凡治兵者，必知氣機。","chunks":[]},{"id":"wu-zi_ch-3_p-4_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-4","order":2,"canonicalText":"氣實則鬥，氣奪則走。","chunks":[]},{"id":"wu-zi_ch-3_p-4_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-4","order":3,"canonicalText":"三軍之眾，百萬之師，志厲青雲，氣若風雷，此所謂氣盛也。","chunks":[]},{"id":"wu-zi_ch-3_p-4_s-4","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-4","order":4,"canonicalText":"將以禮先之，以義厲之，以威嚴之，以恩撫之，則三軍之氣蓄矣。","chunks":[]},{"id":"wu-zi_ch-3_p-4_s-5","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-4","order":5,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-5_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-5","order":1,"canonicalText":"吳子曰：「短兵長兵，各有其用。","chunks":[]},{"id":"wu-zi_ch-3_p-5_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-5","order":2,"canonicalText":"短兵利於險隘，長兵利於平易。","chunks":[]},{"id":"wu-zi_ch-3_p-5_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-5","order":3,"canonicalText":"弩利於遠射，弓利於速發，矛戟利於刺擊，刀劍利於近鬥。","chunks":[]},{"id":"wu-zi_ch-3_p-5_s-4","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-5","order":4,"canonicalText":"短長相雜，遠近相資，此治兵之良法也。","chunks":[]},{"id":"wu-zi_ch-3_p-5_s-5","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-5","order":5,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-7_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-7","order":1,"canonicalText":"吳子曰：「凡戰之法，五人為伍，十人為什，百人為卒，千人為旅，萬人為軍。","chunks":[]},{"id":"wu-zi_ch-3_p-7_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-7","order":2,"canonicalText":"伍長管其伍，什長管其什，卒長管其卒，旅長管其旅，軍將管其軍。","chunks":[]},{"id":"wu-zi_ch-3_p-7_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-7","order":3,"canonicalText":"各守其分，各盡其職，大不得掩小，貴不得凌賤。","chunks":[]},{"id":"wu-zi_ch-3_p-7_s-4","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-7","order":4,"canonicalText":"上下相安，法度明備，此治兵之經也。","chunks":[]},{"id":"wu-zi_ch-3_p-7_s-5","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-7","order":5,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-1","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":1,"canonicalText":"吳子曰：「凡行軍之法，無犯絕水，無逆天時，無臨深谷，無背高山。","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-2","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":2,"canonicalText":"若在平陸，則佔廣易；","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-3","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":3,"canonicalText":"若在山林，則佔險阻。","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-4","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":4,"canonicalText":"審察地形，因利制勝。","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-5","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":5,"canonicalText":"兵不預習，臨戰必擾；","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-6","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":6,"canonicalText":"馬不預習，臨陳必驚。","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-7","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":7,"canonicalText":"故治兵者，貴在素習也。","chunks":[]},{"id":"wu-zi_ch-3_p-8_s-8","chapterId":"wu-zi_ch-3","passageId":"wu-zi_ch-3_p-8","order":8,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-1","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":1,"canonicalText":"吳子曰：「夫總文武者，軍之將也；","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-2","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":2,"canonicalText":"兼剛柔者，兵之事也。","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-3","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":3,"canonicalText":"凡人論將，常思其勇；","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-4","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":4,"canonicalText":"勇之於將，乃數分之一耳。","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-5","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":5,"canonicalText":"夫勇者必輕合，輕合而不知利，未可也。","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-6","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":6,"canonicalText":"故將有五慎：一曰理，二曰備，三曰果，四曰戒，五曰約。","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-7","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":7,"canonicalText":"理者，治眾如治寡；","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-8","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":8,"canonicalText":"備者，出門如見敵；","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-9","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":9,"canonicalText":"果者，臨敵不懷生；","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-10","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":10,"canonicalText":"戒者，雖克如始戰；","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-11","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":11,"canonicalText":"約者，法令省而不煩。","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-12","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":12,"canonicalText":"修此五者，乃可為大將矣。","chunks":[]},{"id":"wu-zi_ch-4_p-1_s-13","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-1","order":13,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-1","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":1,"canonicalText":"吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-2","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":2,"canonicalText":"三軍之眾，百萬之師，志厲青雲，氣若風雷，此氣機也；","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-3","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":3,"canonicalText":"路狹道險，名山大澤，十人守隘，千人莫過，此地機也；","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-4","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":4,"canonicalText":"善用間諜，知敵虛實，出其不意，攻其不備，此事機也；","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-5","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":5,"canonicalText":"陳壘牢固，車騎堅利，士卒勇銳，人百其勇，此力機也。","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-6","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":6,"canonicalText":"知此四者，乃可為大將矣。","chunks":[]},{"id":"wu-zi_ch-4_p-2_s-7","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-2","order":7,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-1","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":1,"canonicalText":"吳子曰：「夫將者，三軍之司命，國家之安危也。","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-2","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":2,"canonicalText":"將不嚴，則三軍憒；","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-3","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":3,"canonicalText":"將不明，則士卒疑；","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-4","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":4,"canonicalText":"將不勇，則三軍餒；","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-5","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":5,"canonicalText":"將不仁，則士卒怨；","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-6","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":6,"canonicalText":"將不智，則軍事敗。","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-7","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":7,"canonicalText":"故求將之道，必審其德，察其材，試其能，然後授之以柄。","chunks":[]},{"id":"wu-zi_ch-4_p-3_s-8","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-3","order":8,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-4_p-4_s-1","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-4","order":1,"canonicalText":"吳子曰：「將有三勝：一曰得道，二曰得地，三曰得人。","chunks":[]},{"id":"wu-zi_ch-4_p-4_s-2","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-4","order":2,"canonicalText":"得道者，令行而民樂；","chunks":[]},{"id":"wu-zi_ch-4_p-4_s-3","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-4","order":3,"canonicalText":"得地者，居高而向陽；","chunks":[]},{"id":"wu-zi_ch-4_p-4_s-4","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-4","order":4,"canonicalText":"得人者，士卒勇而將帥和。","chunks":[]},{"id":"wu-zi_ch-4_p-4_s-5","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-4","order":5,"canonicalText":"兼此三者，天下莫能當也。","chunks":[]},{"id":"wu-zi_ch-4_p-4_s-6","chapterId":"wu-zi_ch-4","passageId":"wu-zi_ch-4_p-4","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":1,"canonicalText":"武侯問曰：「嚴刑峻法，不足以止盜；","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":2,"canonicalText":"重賞厚祿，不足以勸戰。","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":3,"canonicalText":"為之奈何？","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":4,"canonicalText":"」起對曰：「君之賞罰，非不信也，然民未知其貴也。","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":5,"canonicalText":"君若使戰勝之士，上堂飲酒，父老妻兒受爵於庭；","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-6","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":6,"canonicalText":"戰死之士，祠之於廟，撫其孤寡；","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-7","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":7,"canonicalText":"逃奔之士，恥之於市，不齒於鄉。","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-8","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":8,"canonicalText":"如此，則民爭勇赴敵矣。","chunks":[]},{"id":"wu-zi_ch-5_p-1_s-9","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-1","order":9,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-2_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-2","order":1,"canonicalText":"武侯問曰：「敵若大至，逼我城下，內無積聚，外無強援，將何以禦之？","chunks":[]},{"id":"wu-zi_ch-5_p-2_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-2","order":2,"canonicalText":"」起對曰：「城固而守，令民無恐。","chunks":[]},{"id":"wu-zi_ch-5_p-2_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-2","order":3,"canonicalText":"出奇兵以擾其餉道，分精銳以夜襲其營。","chunks":[]},{"id":"wu-zi_ch-5_p-2_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-2","order":4,"canonicalText":"敵雖大至，遠來必疲，糧道若絕，其軍自潰。","chunks":[]},{"id":"wu-zi_ch-5_p-2_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-2","order":5,"canonicalText":"此所謂以逸待勞，以奇制眾也。","chunks":[]},{"id":"wu-zi_ch-5_p-2_s-6","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-2","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-3_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-3","order":1,"canonicalText":"武侯問曰：「遇敵於隘，進退不可，為之奈何？","chunks":[]},{"id":"wu-zi_ch-5_p-3_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-3","order":2,"canonicalText":"」起對曰：「林木險隘，巧用火攻；","chunks":[]},{"id":"wu-zi_ch-5_p-3_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-3","order":3,"canonicalText":"草澤深阻，分伏奇兵。","chunks":[]},{"id":"wu-zi_ch-5_p-3_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-3","order":4,"canonicalText":"先發弩以亂其前，後發銳以衝其後。","chunks":[]},{"id":"wu-zi_ch-5_p-3_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-3","order":5,"canonicalText":"敵不知我之多少，必自潰散矣。","chunks":[]},{"id":"wu-zi_ch-5_p-3_s-6","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-3","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-4_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-4","order":1,"canonicalText":"武侯問曰：「大水氾濫，車騎不便，士卒阻溺，為之奈何？","chunks":[]},{"id":"wu-zi_ch-5_p-4_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-4","order":2,"canonicalText":"」起對曰：「避高就燥，作舟楫以通之；","chunks":[]},{"id":"wu-zi_ch-5_p-4_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-4","order":3,"canonicalText":"築浮橋以濟之。","chunks":[]},{"id":"wu-zi_ch-5_p-4_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-4","order":4,"canonicalText":"順流而放火，乘風而進戰。","chunks":[]},{"id":"wu-zi_ch-5_p-4_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-4","order":5,"canonicalText":"敵居下流，必受其害。","chunks":[]},{"id":"wu-zi_ch-5_p-4_s-6","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-4","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-6_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-6","order":1,"canonicalText":"武侯問曰：「敵若堅壘不出，野無所掠，軍糧將盡，為之奈何？","chunks":[]},{"id":"wu-zi_ch-5_p-6_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-6","order":2,"canonicalText":"」起對曰：「佯退以誘其出，示弱以驕其心。","chunks":[]},{"id":"wu-zi_ch-5_p-6_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-6","order":3,"canonicalText":"設伏於要道，分兵以擊其虛。","chunks":[]},{"id":"wu-zi_ch-5_p-6_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-6","order":4,"canonicalText":"敵見我退，必出追之，伏兵發而其軍破矣。","chunks":[]},{"id":"wu-zi_ch-5_p-6_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-6","order":5,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-9_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-9","order":1,"canonicalText":"武侯問曰：「兩軍相遇，未知彼己之強弱，為之奈何？","chunks":[]},{"id":"wu-zi_ch-5_p-9_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-9","order":2,"canonicalText":"」起對曰：「遣輕騎以試之，薄其前以觀其動。","chunks":[]},{"id":"wu-zi_ch-5_p-9_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-9","order":3,"canonicalText":"動而整者，不可輕擊；","chunks":[]},{"id":"wu-zi_ch-5_p-9_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-9","order":4,"canonicalText":"動而亂者，可乘而破。","chunks":[]},{"id":"wu-zi_ch-5_p-9_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-9","order":5,"canonicalText":"此試敵之法也。","chunks":[]},{"id":"wu-zi_ch-5_p-9_s-6","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-9","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-10_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-10","order":1,"canonicalText":"武侯問曰：「敵若遠來，糧餉不繼，而軍容甚盛，為之奈何？","chunks":[]},{"id":"wu-zi_ch-5_p-10_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-10","order":2,"canonicalText":"」起對曰：「此其虛張聲勢也。","chunks":[]},{"id":"wu-zi_ch-5_p-10_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-10","order":3,"canonicalText":"深溝高壘以持久，設奇以斷其後。","chunks":[]},{"id":"wu-zi_ch-5_p-10_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-10","order":4,"canonicalText":"不出旬日，其軍自乏，乏則必退，退而擊之，可得全勝。","chunks":[]},{"id":"wu-zi_ch-5_p-10_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-10","order":5,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-5_p-11_s-1","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-11","order":1,"canonicalText":"武侯問曰：「敵若乘勝逐北，我軍挫敗，將何以救之？","chunks":[]},{"id":"wu-zi_ch-5_p-11_s-2","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-11","order":2,"canonicalText":"」起對曰：「收散卒以固後陳，設伏兵以斷其追。","chunks":[]},{"id":"wu-zi_ch-5_p-11_s-3","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-11","order":3,"canonicalText":"將帥親自斷後，激勵士卒以必死之志。","chunks":[]},{"id":"wu-zi_ch-5_p-11_s-4","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-11","order":4,"canonicalText":"敵見我有備，追必不深；","chunks":[]},{"id":"wu-zi_ch-5_p-11_s-5","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-11","order":5,"canonicalText":"乘其怠而反擊，敗可復勝也。","chunks":[]},{"id":"wu-zi_ch-5_p-11_s-6","chapterId":"wu-zi_ch-5","passageId":"wu-zi_ch-5_p-11","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-1","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":1,"canonicalText":"武侯問曰：「嚴刑峻法，不足以止盜；","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-2","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":2,"canonicalText":"重賞厚祿，不足以勸戰。","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-3","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":3,"canonicalText":"為之奈何？","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-4","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":4,"canonicalText":"」起對曰：「君之賞罰，非不信也，然民未知其貴也。","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-5","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":5,"canonicalText":"昔者明王勵士，設宴於堂，論功行賞，使有功者顯於天下，無功者恥於閭里。","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-6","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":6,"canonicalText":"如此，則民爭勇赴敵矣。","chunks":[]},{"id":"wu-zi_ch-6_p-1_s-7","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-1","order":7,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-6_p-2_s-1","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-2","order":1,"canonicalText":"武侯乃設宴於堂，坐功臣於前，賜以重器；","chunks":[]},{"id":"wu-zi_ch-6_p-2_s-2","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-2","order":2,"canonicalText":"次功者坐於中，賜以精器；","chunks":[]},{"id":"wu-zi_ch-6_p-2_s-3","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-2","order":3,"canonicalText":"無功者坐於後，食而不賜。","chunks":[]},{"id":"wu-zi_ch-6_p-2_s-4","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-2","order":4,"canonicalText":"又厚撫其父母妻子。","chunks":[]},{"id":"wu-zi_ch-6_p-2_s-5","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-2","order":5,"canonicalText":"於是魏國之士，莫不爭死。","chunks":[]},{"id":"wu-zi_ch-6_p-3_s-1","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-3","order":1,"canonicalText":"兼年，秦興師臨陰晉，魏氏之兵莫不請戰。","chunks":[]},{"id":"wu-zi_ch-6_p-3_s-2","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-3","order":2,"canonicalText":"起請以五萬之眾破之。","chunks":[]},{"id":"wu-zi_ch-6_p-3_s-3","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-3","order":3,"canonicalText":"武侯曰：「秦軍五十萬，子以五萬，奈何？","chunks":[]},{"id":"wu-zi_ch-6_p-3_s-4","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-3","order":4,"canonicalText":"」起曰：「臣之所教五萬人，皆勇銳之士，一人當百。","chunks":[]},{"id":"wu-zi_ch-6_p-3_s-5","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-3","order":5,"canonicalText":"且士卒皆以死為榮，以退為恥，此必勝之勢也。","chunks":[]},{"id":"wu-zi_ch-6_p-3_s-6","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-3","order":6,"canonicalText":"」","chunks":[]},{"id":"wu-zi_ch-6_p-4_s-1","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-4","order":1,"canonicalText":"起乃率車五百乘，騎三千匹，步卒五萬，與秦戰於陰晉。","chunks":[]},{"id":"wu-zi_ch-6_p-4_s-2","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-4","order":2,"canonicalText":"三軍之士，見敵若仇，爭勇先登，大破秦軍五十萬之眾。","chunks":[]},{"id":"wu-zi_ch-6_p-4_s-3","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-4","order":3,"canonicalText":"天下莫不震服。","chunks":[]},{"id":"wu-zi_ch-6_p-5_s-1","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-5","order":1,"canonicalText":"吳子曰：「夫戰勝攻取，非難也；","chunks":[]},{"id":"wu-zi_ch-6_p-5_s-2","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-5","order":2,"canonicalText":"守勝固功，難也。","chunks":[]},{"id":"wu-zi_ch-6_p-5_s-3","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-5","order":3,"canonicalText":"故明君勝而不驕，勇而不暴。","chunks":[]},{"id":"wu-zi_ch-6_p-5_s-4","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-5","order":4,"canonicalText":"賞罰以信，恩威並用，則士卒死義，雖有強敵，何足懼哉！","chunks":[]},{"id":"wu-zi_ch-6_p-5_s-5","chapterId":"wu-zi_ch-6","passageId":"wu-zi_ch-6_p-5","order":5,"canonicalText":"」","chunks":[]}]}') as WorkBundle
